{
  "name": "ComicGen AI",
  "description": "Yapay zeka destekli, 4 panelli çizgi roman oluşturucu. Karakterleri tanımlayın, konuyu belirleyin ve hikayenizi görselleştirin."
}

export interface Character {
  id: string;
  name: string;
  description: string;
}

export interface ComicPanelData {
  imagePrompt: string;
  dialogue: string;
  imageUrl?: string;
  isLoading?: boolean;
}

export interface ComicPage {
  id: string;
  panels: ComicPanelData[];
}

export interface ComicConfig {
  topic: string;
  intro: string;
  cast: Character[];
  style: string;
}

export enum GeneratorStatus {
  IDLE = 'IDLE',
  GENERATING_STORY = 'GENERATING_STORY',
  GENERATING_IMAGES = 'GENERATING_IMAGES',
  COMPLETE = 'COMPLETE',
  ERROR = 'ERROR'
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { ComicConfig, ComicPanelData, Character } from "../types";

// Initialize the client
// The API key is injected automatically via process.env.API_KEY
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const STORY_MODEL = "gemini-3-flash-preview";
const IMAGE_MODEL = "gemini-2.5-flash-image";

/**
 * Generates the script/storyboard for the next 4 panels based on inputs.
 */
export const generateComicScript = async (
  config: ComicConfig,
  history: string[]
): Promise<ComicPanelData[]> => {
  const castDescription = config.cast
    .map((c) => `${c.name} (${c.description})`)
    .join(", ");

  const previousContext = history.length > 0 ? history.join("\n") : "None yet.";

  const prompt = `
    You are a professional comic book writer.
    Topic: ${config.topic}
    Cast: ${castDescription}
    Story Start/Context: ${config.intro}
    Previous Events: ${previousContext}

    Task: Write the script for the NEXT 4 panels of this comic to continue the story.
    Ensure the story moves forward logically.

    For each panel, provide:
    1. 'imagePrompt': A highly detailed visual description of the scene for an AI image generator. Include character appearance, action, setting, and lighting. Describe it as a comic book panel style.
    2. 'dialogue': The text spoken by characters or a narrator caption. Keep it brief enough to fit in a bubble.
  `;

  const responseSchema: Schema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        imagePrompt: {
          type: Type.STRING,
          description: "Visual description for image generation",
        },
        dialogue: {
          type: Type.STRING,
          description: "Dialogue or caption text",
        },
      },
      required: ["imagePrompt", "dialogue"],
    },
  };

  try {
    const response = await ai.models.generateContent({
      model: STORY_MODEL,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        systemInstruction: "You are a comic book creator. Generate exciting and consistent storyboards.",
      },
    });

    const text = response.text;
    if (!text) throw new Error("No script generated");

    return JSON.parse(text) as ComicPanelData[];
  } catch (error) {
    console.error("Script generation error:", error);
    throw error;
  }
};

/**
 * Generates an image for a single panel.
 */
export const generatePanelImage = async (
  panelPrompt: string,
  style: string
): Promise<string> => {
  try {
    const finalPrompt = `Comic book panel, ${style} style. ${panelPrompt}. High quality, vibrant colors, clear outlines.`;

    const response = await ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: finalPrompt,
      config: {
        // No responseMimeType for image models usually, handled by output structure
      }
    });

    // Extract image
    let base64Image = "";
    const parts = response.candidates?.[0]?.content?.parts;

    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          base64Image = part.inlineData.data;
          break;
        }
      }
    }

    if (!base64Image) {
        // Fallback for demo purposes if generation fails or returns text only
        console.warn("No image data found in response, using placeholder.");
        return ""; 
    }

    return `data:image/png;base64,${base64Image}`;
  } catch (error) {
    console.error("Image generation error:", error);
    return ""; // Return empty string on failure to handle gracefully in UI
  }
};

import React, { useState } from "react";
import { Plus, Trash2, BookOpen, User, Play, Loader2 } from "lucide-react";
import { Character, ComicConfig, GeneratorStatus } from "../types";

interface SidebarProps {
  config: ComicConfig;
  setConfig: React.Dispatch<React.SetStateAction<ComicConfig>>;
  onGenerate: () => void;
  status: GeneratorStatus;
}

export const Sidebar: React.FC<SidebarProps> = ({
  config,
  setConfig,
  onGenerate,
  status,
}) => {
  const [newCharName, setNewCharName] = useState("");
  const [newCharDesc, setNewCharDesc] = useState("");

  const handleAddCharacter = () => {
    if (!newCharName.trim()) return;
    const newChar: Character = {
      id: crypto.randomUUID(),
      name: newCharName,
      description: newCharDesc || "Generic appearance",
    };
    setConfig((prev) => ({ ...prev, cast: [...prev.cast, newChar] }));
    setNewCharName("");
    setNewCharDesc("");
  };

  const handleRemoveCharacter = (id: string) => {
    setConfig((prev) => ({
      ...prev,
      cast: prev.cast.filter((c) => c.id !== id),
    }));
  };

  const isLoading = status !== GeneratorStatus.IDLE && status !== GeneratorStatus.COMPLETE && status !== GeneratorStatus.ERROR;

  return (
    <aside className="w-full md:w-80 bg-gray-900 text-gray-100 h-screen flex flex-col border-r border-gray-800 overflow-y-auto custom-scrollbar">
      <div className="p-6">
        <h1 className="text-2xl font-bold bg-gradient-to-r from-yellow-400 to-orange-500 bg-clip-text text-transparent mb-6 flex items-center gap-2">
          <BookOpen className="text-yellow-400" />
          ComicGen AI
        </h1>

        {/* Topic Section */}
        <div className="mb-6 space-y-2">
          <label className="text-xs font-semibold text-gray-400 uppercase tracking-wider">
            Çizgi Roman Konusu
          </label>
          <textarea
            className="w-full bg-gray-800 border border-gray-700 rounded p-3 text-sm focus:ring-2 focus:ring-yellow-500 outline-none resize-none h-20"
            placeholder="Örn: Uzayda geçen bir kovboy hikayesi..."
            value={config.topic}
            onChange={(e) =>
              setConfig((prev) => ({ ...prev, topic: e.target.value }))
            }
          />
        </div>

        {/* Intro Section */}
        <div className="mb-6 space-y-2">
          <label className="text-xs font-semibold text-gray-400 uppercase tracking-wider">
            Hikaye Girişi
          </label>
          <textarea
            className="w-full bg-gray-800 border border-gray-700 rounded p-3 text-sm focus:ring-2 focus:ring-yellow-500 outline-none resize-none h-24"
            placeholder="Hikaye nasıl başlıyor?..."
            value={config.intro}
            onChange={(e) =>
              setConfig((prev) => ({ ...prev, intro: e.target.value }))
            }
          />
        </div>

         {/* Style Section */}
         <div className="mb-6 space-y-2">
          <label className="text-xs font-semibold text-gray-400 uppercase tracking-wider">
            Görsel Stil
          </label>
          <select
            className="w-full bg-gray-800 border border-gray-700 rounded p-2 text-sm focus:ring-2 focus:ring-yellow-500 outline-none"
            value={config.style}
            onChange={(e) => setConfig(prev => ({ ...prev, style: e.target.value }))}
          >
            <option value="Classic Comic Book">Klasik Çizgi Roman</option>
            <option value="Manga">Manga / Anime</option>
            <option value="Noir">Noir / Siyah Beyaz</option>
            <option value="Cyberpunk">Cyberpunk</option>
            <option value="Watercolor">Sulu Boya</option>
          </select>
        </div>

        {/* Cast Section */}
        <div className="mb-6">
          <div className="flex justify-between items-center mb-2">
            <label className="text-xs font-semibold text-gray-400 uppercase tracking-wider">
              Cast Kadrosu
            </label>
            <span className="text-xs text-gray-500">{config.cast.length} Karakter</span>
          </div>

          <div className="bg-gray-800 rounded-lg p-3 space-y-3 mb-3 border border-gray-700">
            <div className="space-y-2">
              <input
                type="text"
                placeholder="İsim (Örn: Dedektif John)"
                className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-xs focus:border-yellow-500 outline-none"
                value={newCharName}
                onChange={(e) => setNewCharName(e.target.value)}
              />
              <input
                type="text"
                placeholder="Görünüm (Örn: Uzun pardesü, şapka)"
                className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-xs focus:border-yellow-500 outline-none"
                value={newCharDesc}
                onChange={(e) => setNewCharDesc(e.target.value)}
              />
              <button
                onClick={handleAddCharacter}
                disabled={!newCharName.trim()}
                className="w-full bg-gray-700 hover:bg-gray-600 text-white text-xs py-2 rounded flex items-center justify-center gap-1 transition-colors disabled:opacity-50"
              >
                <Plus size={14} /> Karakter Ekle
              </button>
            </div>
          </div>

          <div className="space-y-2 max-h-48 overflow-y-auto pr-1">
            {config.cast.map((char) => (
              <div
                key={char.id}
                className="flex items-start justify-between bg-gray-800/50 p-2 rounded border border-gray-700"
              >
                <div className="flex items-start gap-2 overflow-hidden">
                  <div className="bg-gray-700 p-1 rounded mt-0.5">
                    <User size={12} className="text-gray-400" />
                  </div>
                  <div className="min-w-0">
                    <p className="text-sm font-medium text-gray-200 truncate">{char.name}</p>
                    <p className="text-xs text-gray-400 truncate">{char.description}</p>
                  </div>
                </div>
                <button
                  onClick={() => handleRemoveCharacter(char.id)}
                  className="text-gray-500 hover:text-red-400 transition-colors p-1"
                >
                  <Trash2 size={14} />
                </button>
              </div>
            ))}
            {config.cast.length === 0 && (
              <p className="text-xs text-gray-500 text-center py-2 italic">
                Henüz karakter eklenmedi.
