            )}
          </div>
        </div>
      </div>

      <div className="p-6 mt-auto border-t border-gray-800 bg-gray-900 sticky bottom-0">
        <button
          onClick={onGenerate}
          disabled={isLoading || !config.topic || !config.intro}
          className={`w-full py-4 rounded-xl font-bold text-lg flex items-center justify-center gap-2 shadow-lg transition-all
            ${
              isLoading
                ? "bg-gray-700 text-gray-400 cursor-not-allowed"
                : "bg-yellow-500 hover:bg-yellow-400 text-gray-900 hover:scale-[1.02]"
            }
          `}
        >
          {isLoading ? (
            <>
              <Loader2 className="animate-spin" />
              {status === GeneratorStatus.GENERATING_STORY ? "Hikaye Yazılıyor..." : "Çiziliyor..."}
            </>
          ) : (
            <>
              <Play className="fill-current" />
              Çizgi Romanı Başlat
            </>
          )}
        </button>
      </div>
    </aside>
  );
};

import React from "react";
import { ComicPage } from "../types";
import { Loader2 } from "lucide-react";

interface ComicPageDisplayProps {
  page: ComicPage;
  pageIndex: number;
}

export const ComicPageDisplay: React.FC<ComicPageDisplayProps> = ({ page, pageIndex }) => {
  return (
    <div className="bg-white p-4 shadow-2xl max-w-4xl mx-auto mb-12 transform rotate-0 hover:rotate-0 transition-transform duration-500">
      <div className="border-4 border-black p-1 bg-white">
        {/* Header/Page Number */}
