      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from "react";
import { Sidebar } from "./components/Sidebar";
import { ComicPageDisplay } from "./components/ComicPageDisplay";
import {
  ComicConfig,
  ComicPage,
  GeneratorStatus,
  ComicPanelData,
} from "./types";
import { generateComicScript, generatePanelImage } from "./services/geminiService";
import { PlusCircle, Info, Ghost } from "lucide-react";

export default function App() {
  const [config, setConfig] = useState<ComicConfig>({
    topic: "",
    intro: "",
    cast: [],
    style: "Classic Comic Book"
  });

  const [pages, setPages] = useState<ComicPage[]>([]);
  const [status, setStatus] = useState<GeneratorStatus>(GeneratorStatus.IDLE);
  const bottomRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom when new pages are added
  useEffect(() => {
    if (pages.length > 0) {
      bottomRef.current?.scrollIntoView({ behavior: "smooth" });
    }
  }, [pages.length, status]);

  const handleGenerateNextPage = async () => {
    if (status !== GeneratorStatus.IDLE && status !== GeneratorStatus.COMPLETE && status !== GeneratorStatus.ERROR) return;

    try {
      setStatus(GeneratorStatus.GENERATING_STORY);

      // Create a skeleton page
      const newPageId = crypto.randomUUID();
      const skeletonPanels: ComicPanelData[] = Array(4).fill({
        imagePrompt: "",
        dialogue: "",
        isLoading: true,
      });

      const newPage: ComicPage = {
        id: newPageId,
        panels: skeletonPanels,
      };

      setPages((prev) => [...prev, newPage]);

      // 1. Generate Script
      // Collect dialogue history for context
      const history = pages.flatMap(p => p.panels.map(panel => panel.dialogue));
      const scriptPanels = await generateComicScript(config, history);

      // Update page with text, keep loading spinners for images
      setPages((prev) =>
        prev.map((p) =>
          p.id === newPageId
            ? {
                ...p,
                panels: scriptPanels.map((sp) => ({
                  ...sp,
                  isLoading: true, // still loading image
                })),
              }
            : p
        )
      );

      setStatus(GeneratorStatus.GENERATING_IMAGES);

      // 2. Generate Images (Parallel)
      const imagePromises = scriptPanels.map((panel, index) =>
        generatePanelImage(panel.imagePrompt, config.style).then((imageUrl) => ({
          index,
          imageUrl,
        }))
      );

      // Process images as they finish or wait for all? 
      // Waiting for all is cleaner for state updates, though incremental is cooler.
      // Let's do Promise.all for simplicity in this complexity.
      const results = await Promise.all(imagePromises);

      // Update state with images
      setPages((prev) =>
        prev.map((p) =>
          p.id === newPageId
            ? {
                ...p,
                panels: p.panels.map((panel, idx) => {
                  const img = results.find((r) => r.index === idx);
                  return {
                    ...panel,
                    imageUrl: img?.imageUrl,
                    isLoading: false,
                  };
                }),
              }
            : p
        )
      );

      setStatus(GeneratorStatus.COMPLETE);
    } catch (error) {
      console.error("Generation failed", error);
      setStatus(GeneratorStatus.ERROR);
      // Remove the skeleton page if it failed completely during script generation
      if (status === GeneratorStatus.GENERATING_STORY) {
         setPages(prev => prev.slice(0, -1));
      }
    }
  };

  return (
    <div className="flex flex-col md:flex-row min-h-screen bg-gray-100 font-sans">
      {/* Left Sidebar */}
      <Sidebar
        config={config}
        setConfig={setConfig}
        onGenerate={handleGenerateNextPage}
        status={status}
      />

      {/* Main Content Area */}
      <main className="flex-1 h-screen overflow-y-auto bg-slate-200 relative custom-scrollbar">
        {/* Background Pattern */}
        <div className="absolute inset-0 opacity-5 pointer-events-none" 
             style={{ 
               backgroundImage: 'radial-gradient(circle, #000 1px, transparent 1px)', 
               backgroundSize: '20px 20px' 
             }} 
        />

        <div className="max-w-5xl mx-auto px-4 py-8 relative z-10 min-h-full flex flex-col">

          {/* Empty State */}
          {pages.length === 0 && (
            <div className="flex-1 flex flex-col items-center justify-center text-center text-gray-500 opacity-60">
              <Ghost size={64} className="mb-4 text-gray-400" />
              <h2 className="text-2xl font-bold text-gray-600 mb-2">Hikaye Başlamadı</h2>
              <p className="max-w-md">Soldaki menüden karakterleri ekleyin, konuyu yazın ve "Çizgi Romanı Başlat" butonuna basın.</p>
            </div>
          )}

          {/* Comic Pages */}
          <div className="space-y-8 pb-32">
            {pages.map((page, index) => (
              <ComicPageDisplay key={page.id} page={page} pageIndex={index} />
            ))}

            {/* Error State */}
            {status === GeneratorStatus.ERROR && (
              <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 rounded shadow-sm mx-auto max-w-lg">
                <p className="font-bold">Bir hata oluştu</p>
                <p>İçerik üretilirken bir sorun yaşandı. Lütfen tekrar deneyin.</p>
              </div>
            )}

            <div ref={bottomRef} />
          </div>
        </div>

        {/* Floating Action Button (Only visible if we have pages and not generating) */}
        {pages.length > 0 && status === GeneratorStatus.COMPLETE && (
            <div className="fixed bottom-8 right-8 z-50">
                <button 
                    onClick={handleGenerateNextPage}
                    className="bg-yellow-500 hover:bg-yellow-400 text-black border-2 border-black font-bold py-3 px-6 rounded-full shadow-[4px_4px_0px_rgba(0,0,0,1)] flex items-center gap-2 hover:-translate-y-1 transition-transform"
                >
                    <PlusCircle size={24} />
                    Sonraki Sayfayı Çiz
                </button>
            </div>
        )}
      </main>
    </div>
  );
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Character {
  id: string;
  name: string;
  description: string;
  avatarUrl?: string;
}

export interface ComicPanelData {
  imagePrompt: string;
  dialogue: string;
  imageUrl?: string;
  isLoading?: boolean;
}

export interface ComicPage {
  id: string;
  panels: ComicPanelData[];
}

export interface ComicConfig {
  topic: string;
  intro: string;
  cast: Character[];
  style: string;
}

export enum GeneratorStatus {
  IDLE = 'IDLE',
  GENERATING_STORY = 'GENERATING_STORY',
  GENERATING_IMAGES = 'GENERATING_IMAGES',
  COMPLETE = 'COMPLETE',
  ERROR = 'ERROR'
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { ComicConfig, ComicPanelData, Character } from "../types";

// Initialize the client
// The API key is injected automatically via process.env.API_KEY
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const STORY_MODEL = "gemini-3-flash-preview";
const IMAGE_MODEL = "gemini-2.5-flash-image";

/**
 * Generates an avatar image for a character.
 */
export const generateCharacterAvatar = async (
  name: string,
  description: string,
  style: string
): Promise<string> => {
  try {
    const prompt = `Character portrait, headshot of ${name}, ${description}. Art style: ${style}. White background, high quality, character design sheet style.`;

    const response = await ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: prompt,
    });

    let base64Image = "";
    const parts = response.candidates?.[0]?.content?.parts;

    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          base64Image = part.inlineData.data;
          break;
        }
      }
    }

    if (!base64Image) return "";
    return `data:image/png;base64,${base64Image}`;
  } catch (error) {
    console.error("Avatar generation error:", error);
    return "";
  }
};

/**
 * Generates the script/storyboard for the next 4 panels based on inputs.
 */
export const generateComicScript = async (
  config: ComicConfig,
  history: string[]
): Promise<ComicPanelData[]> => {
  const castDescription = config.cast
    .map((c) => `${c.name} (${c.description})`)
    .join(", ");

  const previousContext = history.length > 0 ? history.join("\n") : "None yet.";

  const prompt = `
    You are a professional comic book writer.
    Topic: ${config.topic}
    Cast: ${castDescription}
    Story Start/Context: ${config.intro}
    Previous Events: ${previousContext}

    Task: Write the script for the NEXT 4 panels of this comic to continue the story.
    Ensure the story moves forward logically.

    For each panel, provide:
    1. 'imagePrompt': A highly detailed visual description of the scene for an AI image generator. Include character appearance, action, setting, and lighting. Describe it as a comic book panel style.
    2. 'dialogue': The text spoken by characters or a narrator caption. Keep it brief enough to fit in a bubble.
  `;

  const responseSchema: Schema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        imagePrompt: {
          type: Type.STRING,
          description: "Visual description for image generation",
        },
        dialogue: {
          type: Type.STRING,
          description: "Dialogue or caption text",
        },
      },
      required: ["imagePrompt", "dialogue"],
    },
  };

  try {
    const response = await ai.models.generateContent({
      model: STORY_MODEL,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        systemInstruction: "You are a comic book creator. Generate exciting and consistent storyboards.",
      },
    });

    const text = response.text;
    if (!text) throw new Error("No script generated");

    return JSON.parse(text) as ComicPanelData[];
  } catch (error) {
    console.error("Script generation error:", error);
    throw error;
  }
};

/**
 * Generates an image for a single panel.
 */
export const generatePanelImage = async (
  panelPrompt: string,
  style: string
): Promise<string> => {
  try {
    const finalPrompt = `Comic book panel, ${style} style. ${panelPrompt}. High quality, vibrant colors, clear outlines.`;

    const response = await ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: finalPrompt,
      config: {
        // No responseMimeType for image models usually, handled by output structure
      }
    });

    // Extract image
    let base64Image = "";
    const parts = response.candidates?.[0]?.content?.parts;

    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          base64Image = part.inlineData.data;
          break;
        }
      }
    }

    if (!base64Image) {
        // Fallback for demo purposes if generation fails or returns text only
        console.warn("No image data found in response, using placeholder.");
        return ""; 
    }

    return `data:image/png;base64,${base64Image}`;
  } catch (error) {
    console.error("Image generation error:", error);
    return ""; // Return empty string on failure to handle gracefully in UI
  }
};

import React, { useState } from "react";
import { Plus, Trash2, BookOpen, User, Play, Loader2, Sparkles } from "lucide-react";
