        <div className="mb-6 space-y-2">
          <label className="text-xs font-semibold text-gray-400 uppercase tracking-wider">
            Çizgi Roman Konusu
          </label>
          <textarea
            className="w-full bg-gray-800 border border-gray-700 rounded p-3 text-sm focus:ring-2 focus:ring-yellow-500 outline-none resize-none h-20"
            placeholder="Örn: Uzayda geçen bir kovboy hikayesi..."
            value={config.topic}
            onChange={(e) =>
              setConfig((prev) => ({ ...prev, topic: e.target.value }))
            }
          />
        </div>

        {/* Intro Section */}
        <div className="mb-6 space-y-2">
          <label className="text-xs font-semibold text-gray-400 uppercase tracking-wider">
            Hikaye Girişi
          </label>
