              <p className="max-w-md">Soldaki menüyü açarak karakterleri ekleyin, konuyu yazın ve "Çizgi Romanı Başlat" butonuna basın.</p>
            </div>
          )}

          {/* Comic Pages */}
          <div className="space-y-8 pb-32">
            {pages.map((page, index) => (
              <ComicPageDisplay 
                key={page.id} 
                page={page} 
                pageIndex={index} 
                onPanelClick={(url) => setPreviewImage(url)}
              />
            ))}

            {/* Error State */}
            {status === GeneratorStatus.ERROR && (
              <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 rounded shadow-sm mx-auto max-w-lg">
                <p className="font-bold">Bir hata oluştu</p>
                <p>İçerik üretilirken bir sorun yaşandı. Lütfen tekrar deneyin.</p>
              </div>
            )}

            <div ref={bottomRef} />
          </div>
        </div>

        {/* Floating Action Button (Only visible if we have pages and not generating) */}
        {pages.length > 0 && status === GeneratorStatus.COMPLETE && (
            <div className="fixed bottom-8 right-8 z-20">
                <button 
                    onClick={handleNextPageClick}
                    className="bg-yellow-500 hover:bg-yellow-400 text-black border-2 border-black font-bold py-3 px-6 rounded-full shadow-[4px_4px_0px_rgba(0,0,0,1)] flex items-center gap-2 hover:-translate-y-1 transition-transform"
                >
                    <PlusCircle size={24} />
                    Sonraki Sayfayı Çiz
                </button>
