interface SidebarProps {
  config: ComicConfig;
  setConfig: React.Dispatch<React.SetStateAction<ComicConfig>>;
  onGenerate: () => void;
  status: GeneratorStatus;
  isOpen: boolean;
  onToggle: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({
  config,
  setConfig,
  onGenerate,
  status,
  isOpen,
  onToggle,
}) => {
  const [newCharName, setNewCharName] = useState("");
  const [newCharDesc, setNewCharDesc] = useState("");
  const [isGeneratingAvatar, setIsGeneratingAvatar] = useState(false);
  const [previewImage, setPreviewImage] = useState<string | null>(null);

  const handleAddCharacter = async () => {
    if (!newCharName.trim()) return;

    setIsGeneratingAvatar(true);

    try {
        // Generate avatar immediately
        const avatarUrl = await generateCharacterAvatar(newCharName, newCharDesc, config.style);

        const newChar: Character = {
            id: crypto.randomUUID(),
            name: newCharName,
            description: newCharDesc || "Generic appearance",
            avatarUrl: avatarUrl
        };

        setConfig((prev) => ({ ...prev, cast: [...prev.cast, newChar] }));
        setNewCharName("");
        setNewCharDesc("");
    } catch (e) {
        console.error("Avatar error", e);
        // Add without avatar if fails
        const newChar: Character = {
            id: crypto.randomUUID(),
            name: newCharName,
            description: newCharDesc || "Generic appearance",
        };
        setConfig((prev) => ({ ...prev, cast: [...prev.cast, newChar] }));
    } finally {
        setIsGeneratingAvatar(false);
    }
  };

  const handleRemoveCharacter = (id: string) => {
    setConfig((prev) => ({
      ...prev,
      cast: prev.cast.filter((c) => c.id !== id),
    }));
  };

  const isLoading = status !== GeneratorStatus.IDLE && status !== GeneratorStatus.COMPLETE && status !== GeneratorStatus.ERROR;

  return (
    <>
      <aside 
        className={`
            fixed inset-y-0 left-0 z-40 h-screen bg-gray-900 text-gray-100 flex flex-col border-r border-gray-800 shadow-2xl transition-all duration-300 ease-in-out
            ${isOpen ? "translate-x-0" : "-translate-x-full"} 
