            <button
                onClick={onGenerate}
                disabled={isLoading || !config.topic || !config.intro}
                className={`w-full py-4 rounded-xl font-bold text-lg flex items-center justify-center gap-2 shadow-lg transition-all
                ${
                    isLoading
                    ? "bg-gray-700 text-gray-400 cursor-not-allowed"
                    : "bg-yellow-500 hover:bg-yellow-400 text-gray-900 hover:scale-[1.02]"
