    1. 'imagePrompt': A highly detailed visual description of the scene. Include character appearance, action, setting, and lighting. Describe it as a comic book panel style. ALWAYS include the character names clearly in the prompt if they appear.
    2. 'dialogue': The text spoken by characters or a narrator caption. Keep it brief.
  `;

  const responseSchema: Schema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        imagePrompt: {
          type: Type.STRING,
          description: "Visual description for image generation",
        },
        dialogue: {
          type: Type.STRING,
          description: "Dialogue or caption text",
        },
      },
      required: ["imagePrompt", "dialogue"],
    },
  };

  try {
    const response = await ai.models.generateContent({
      model: STORY_MODEL,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        systemInstruction: "You are a comic book creator. Generate exciting and consistent storyboards.",
      },
    });

    const text = response.text;
    if (!text) throw new Error("No script generated");

    return JSON.parse(text) as ComicPanelData[];
  } catch (error) {
    console.error("Script generation error:", error);
    throw error;
  }
};

/**
 * Generates a SINGLE full-page image containing a 2x2 grid of panels.
 * This saves quota by making 1 API call instead of 4.
 */
export const generateFullPageImage = async (
  panels: ComicPanelData[],
  style: string,
  cast: Character[]
): Promise<string> => {
  try {
    const parts: any[] = [];

    // 1. Construct a master prompt that describes the 2x2 layout
    let layoutDescription = `
      Create a full Comic Book Page with a STRICT 2x2 GRID LAYOUT (4 panels total).
      Art Style: ${style}.
      Quality: High definition, vibrant colors, clean thick panel borders (gutters).

      Content:
    `;

    panels.forEach((p, i) => {
        const position = i === 0 ? "Top-Left" : i === 1 ? "Top-Right" : i === 2 ? "Bottom-Left" : "Bottom-Right";
        layoutDescription += `\nPANEL ${i+1} (${position}): ${p.imagePrompt}`;
    });

    // 2. Identify all characters present in the entire page for reference
    const uniqueCharactersInPage = new Set<string>();
    panels.forEach(p => {
        cast.forEach(c => {
            if (p.imagePrompt.toLowerCase().includes(c.name.toLowerCase())) {
                uniqueCharactersInPage.add(c.id);
            }
        });
    });

    // 3. Add reference images for consistent characters
    const matchedCharacters = cast.filter(c => uniqueCharactersInPage.has(c.id) && c.avatarUrl);

    let referenceInstructions = "";
    if (matchedCharacters.length > 0) {
        referenceInstructions = "\n\nIMPORTANT REFERENCE INSTRUCTIONS: Maintain exact character consistency (face, hair, clothing) for the following characters based on the attached reference images: " + matchedCharacters.map(c => c.name).join(", ") + ".";

        for (const char of matchedCharacters) {
            if (char.avatarUrl) {
                // Remove the data URL prefix to get raw base64
                const base64Data = char.avatarUrl.split(',')[1];
                parts.push({
                    inlineData: {
                        data: base64Data,
                        mimeType: "image/png"
                    }
                });
            }
        }
    }

    const finalPrompt = `${layoutDescription} ${referenceInstructions}`;

    // Add text prompt as the last part
    parts.push({ text: finalPrompt });

    const response = await ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: { parts: parts },
      config: {
          aspectRatio: "1:1", // Square page for 2x2 grid
          imageSize: "1K" // Standard resolution is fine
      }
    });

    // Extract image
    let base64Image = "";
    const resParts = response.candidates?.[0]?.content?.parts;

    if (resParts) {
      for (const part of resParts) {
        if (part.inlineData && part.inlineData.data) {
          base64Image = part.inlineData.data;
          break;
        }
      }
    }

    if (!base64Image) {
        console.warn("No image data found in response.");
        return ""; 
    }

    return `data:image/png;base64,${base64Image}`;
  } catch (error) {
    console.error("Image generation error:", error);
    return ""; 
  }
};

import React, { useState, useRef, useEffect } from "react";
import { Sidebar } from "./components/Sidebar";
import { ComicPageDisplay } from "./components/ComicPageDisplay";
import {
  ComicConfig,
  ComicPage,
  GeneratorStatus,
  ComicPanelData,
} from "./types";
import { generateComicScript, generateFullPageImage } from "./services/geminiService";
import { PlusCircle, Info, Ghost, X, Send, Menu } from "lucide-react";

export default function App() {
  const [config, setConfig] = useState<ComicConfig>({
    topic: "",
    intro: "",
    cast: [],
    style: "Classic Comic Book"
  });

  const [pages, setPages] = useState<ComicPage[]>([]);
  const [status, setStatus] = useState<GeneratorStatus>(GeneratorStatus.IDLE);

  // States for Modals
  const [showNextPageModal, setShowNextPageModal] = useState(false);
  const [userDirection, setUserDirection] = useState("");
  const [previewImage, setPreviewImage] = useState<string | null>(null);

  // Sidebar State
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  const bottomRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom when new pages are added
  useEffect(() => {
    if (pages.length > 0) {
      bottomRef.current?.scrollIntoView({ behavior: "smooth" });
    }
  }, [pages.length, status]);

  // Initial Responsive Sidebar Check
  useEffect(() => {
    const handleResize = () => {
        if (window.innerWidth < 768) {
            setIsSidebarOpen(false);
        } else {
            setIsSidebarOpen(true);
        }
    };
    // Set initial state based on current width (only on mount)
    if (window.innerWidth < 768) setIsSidebarOpen(false);

    // Optional: Auto-close on resize to mobile could be annoying, so we just set initial.
  }, []);

  const handleStartGeneration = async () => {
     // Close sidebar on mobile when generation starts to see content
     if (window.innerWidth < 768) {
         setIsSidebarOpen(false);
     }
     // Initial start doesn't need a specific next-page prompt, uses intro
     await performGeneration("");
  };

  const handleNextPageClick = () => {
    setUserDirection("");
    setShowNextPageModal(true);
  };

  const confirmNextPageGeneration = () => {
    setShowNextPageModal(false);
    performGeneration(userDirection);
  };

  const performGeneration = async (direction: string) => {
    if (status !== GeneratorStatus.IDLE && status !== GeneratorStatus.COMPLETE && status !== GeneratorStatus.ERROR) return;

    try {
      setStatus(GeneratorStatus.GENERATING_STORY);

      // Create a skeleton page
      const newPageId = crypto.randomUUID();
      const skeletonPanels: ComicPanelData[] = Array(4).fill({
        imagePrompt: "",
        dialogue: "",
        isLoading: true,
      });

      const newPage: ComicPage = {
        id: newPageId,
        panels: skeletonPanels,
      };

      setPages((prev) => [...prev, newPage]);

      // 1. Generate Script
      // Collect dialogue history for context
      const history = pages.flatMap(p => p.panels.map(panel => panel.dialogue));
      const scriptPanels = await generateComicScript(config, history, direction);

      // Update page with text, keep loading spinners
      setPages((prev) =>
        prev.map((p) =>
          p.id === newPageId
            ? {
                ...p,
                panels: scriptPanels.map((sp) => ({
                  ...sp,
                  isLoading: true, // still loading image
                })),
              }
            : p
        )
      );

      setStatus(GeneratorStatus.GENERATING_IMAGES);

      // 2. Generate Single Full Page Image (Saves Quota)
      // Pass config.cast so the service can use avatars as reference
      const fullPageImageUrl = await generateFullPageImage(scriptPanels, config.style, config.cast);

      // Update state with single image and remove loading
      setPages((prev) =>
        prev.map((p) =>
          p.id === newPageId
            ? {
                ...p,
                pageImageUrl: fullPageImageUrl,
                panels: p.panels.map((panel) => ({
                  ...panel,
                  isLoading: false,
                })),
              }
            : p
        )
      );

      setStatus(GeneratorStatus.COMPLETE);
    } catch (error) {
      console.error("Generation failed", error);
      setStatus(GeneratorStatus.ERROR);
      // Remove the skeleton page if it failed completely during script generation
      if (status === GeneratorStatus.GENERATING_STORY) {
         setPages(prev => prev.slice(0, -1));
      }
    }
  };

  return (
    <div className="flex flex-col md:flex-row min-h-screen bg-gray-100 font-sans relative overflow-hidden">
      {/* Left Sidebar */}
      <Sidebar
        config={config}
        setConfig={setConfig}
        onGenerate={handleStartGeneration}
        status={status}
        isOpen={isSidebarOpen}
        onToggle={() => setIsSidebarOpen(!isSidebarOpen)}
      />

      {/* Mobile Sidebar Backdrop */}
      {isSidebarOpen && (
          <div 
            className="fixed inset-0 bg-black/50 z-30 md:hidden" 
            onClick={() => setIsSidebarOpen(false)}
          />
      )}

      {/* Toggle Button (Visible when closed) */}
      {!isSidebarOpen && (
        <button
          onClick={() => setIsSidebarOpen(true)}
          className="fixed top-4 left-4 z-20 p-2 bg-yellow-500 rounded-lg shadow-lg hover:bg-yellow-400 text-gray-900 transition-colors border-2 border-black"
          aria-label="Open Menu"
        >
          <Menu size={24} />
        </button>
      )}

      {/* Main Content Area */}
      <main className="flex-1 h-screen overflow-y-auto bg-slate-200 relative custom-scrollbar">
        {/* Background Pattern */}
        <div className="absolute inset-0 opacity-5 pointer-events-none" 
             style={{ 
               backgroundImage: 'radial-gradient(circle, #000 1px, transparent 1px)', 
               backgroundSize: '20px 20px' 
             }} 
        />

        <div className="max-w-5xl mx-auto px-4 py-8 relative z-10 min-h-full flex flex-col">

          {/* Header Spacer for Toggle Button when visible */}
          {!isSidebarOpen && <div className="h-12 md:h-0" />}

          {/* Empty State */}
          {pages.length === 0 && (
            <div className="flex-1 flex flex-col items-center justify-center text-center text-gray-500 opacity-60">
              <Ghost size={64} className="mb-4 text-gray-400" />
              <h2 className="text-2xl font-bold text-gray-600 mb-2">Hikaye Başlamadı</h2>
              <p className="max-w-md">Soldaki menüyü açarak karakterleri ekleyin, konuyu yazın ve "Çizgi Romanı Başlat" butonuna basın.</p>
            </div>
          )}

          {/* Comic Pages */}
          <div className="space-y-8 pb-32">
            {pages.map((page, index) => (
              <ComicPageDisplay 
                key={page.id} 
                page={page} 
                pageIndex={index} 
                onPanelClick={(url) => setPreviewImage(url)}
              />
            ))}

            {/* Error State */}
            {status === GeneratorStatus.ERROR && (
              <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 rounded shadow-sm mx-auto max-w-lg">
                <p className="font-bold">Bir hata oluştu</p>
                <p>İçerik üretilirken bir sorun yaşandı. Lütfen tekrar deneyin.</p>
              </div>
            )}

            <div ref={bottomRef} />
          </div>
        </div>

        {/* Floating Action Button (Only visible if we have pages and not generating) */}
        {pages.length > 0 && status === GeneratorStatus.COMPLETE && (
            <div className="fixed bottom-8 right-8 z-20">
                <button 
                    onClick={handleNextPageClick}
                    className="bg-yellow-500 hover:bg-yellow-400 text-black border-2 border-black font-bold py-3 px-6 rounded-full shadow-[4px_4px_0px_rgba(0,0,0,1)] flex items-center gap-2 hover:-translate-y-1 transition-transform"
                >
                    <PlusCircle size={24} />
                    Sonraki Sayfayı Çiz
                </button>
            </div>
        )}

        {/* User Direction Modal */}
        {showNextPageModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden border-4 border-black animate-in fade-in zoom-in duration-200">
               <div className="bg-yellow-400 p-4 border-b-4 border-black flex justify-between items-center">
                  <h3 className="font-display text-xl uppercase tracking-wider text-black">Devam Et</h3>
                  <button onClick={() => setShowNextPageModal(false)} className="text-black hover:text-white transition-colors">
                    <X size={24} />
                  </button>
               </div>
               <div className="p-6">
                 <label className="block text-sm font-bold text-gray-700 mb-2 font-comic uppercase">
                    Bu bölümde ne olsun?
                 </label>
                 <textarea 
                    className="w-full h-32 bg-gray-100 border-2 border-gray-300 rounded p-4 text-gray-800 focus:border-yellow-500 focus:ring-0 outline-none resize-none font-comic text-lg"
                    placeholder="Örn: Kahramanlar gizli geçidi bulur ama tuzak çalışır..."
                    value={userDirection}
                    onChange={(e) => setUserDirection(e.target.value)}
                    autoFocus
                 />
                 <p className="text-xs text-gray-500 mt-2">
                   * Boş bırakırsanız yapay zeka hikayeyi kendi kurgusuna göre devam ettirir.
                 </p>
               </div>
               <div className="bg-gray-100 p-4 border-t-2 border-gray-200 flex justify-end gap-3">
                  <button 
                    onClick={() => setShowNextPageModal(false)}
                    className="px-4 py-2 font-bold text-gray-500 hover:text-black transition-colors"
                  >
                    İptal
                  </button>
                  <button 
                    onClick={confirmNextPageGeneration}
                    className="px-6 py-2 bg-black text-white font-bold rounded hover:bg-gray-800 transition-colors flex items-center gap-2 shadow-[2px_2px_0px_#fbbf24]"
                  >
                    <Send size={16} />
                    Oluştur
                  </button>
               </div>
            </div>
          </div>
        )}

        {/* Global Image Preview Modal */}
        {previewImage && (
          <div 
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/95 p-4 backdrop-blur-md animate-in fade-in duration-200"
            onClick={() => setPreviewImage(null)}
          >
            <div className="relative max-w-5xl w-full max-h-[90vh] flex items-center justify-center">
              <button 
                  onClick={() => setPreviewImage(null)}
                  className="absolute -top-12 right-0 text-white hover:text-yellow-400 transition-colors bg-white/10 p-2 rounded-full"
              >
                  <X size={24} />
              </button>
              <img 
                  src={previewImage} 
                  alt="Full Size Panel" 
                  className="max-w-full max-h-[85vh] object-contain rounded border-4 border-gray-800 shadow-2xl"
                  onClick={(e) => e.stopPropagation()} 
              />
            </div>
          </div>
        )}

      </main>
    </div>
  );
}

