                                className="p-1.5 bg-white border-2 border-black rounded-full hover:bg-yellow-400 hover:scale-110 transition-all shadow-sm"
                                title="Bu kareyi yeniden çiz"
                            >
                                <RefreshCw size={14} className={panel.isLoading ? "animate-spin" : ""} />
                            </button>
                            <button
                                onClick={(e) => {
                                    e.stopPropagation();
                                    onPanelClick(panel.imageUrl || page.pageImageUrl || "");
                                }}
                                className="p-1.5 bg-white border-2 border-black rounded-full hover:bg-yellow-400 hover:scale-110 transition-all shadow-sm"
                                title="Büyüt"
                            >
                                <Maximize2 size={14} />
                            </button>
                        </div>

                        {/* Loading placeholder for single panel regeneration */}
                        {panel.isLoading && (
                            <div className="absolute inset-0 bg-black/50 z-10 flex items-center justify-center backdrop-blur-sm">
                                <Loader2 className="text-white animate-spin" size={24} />
                            </div>
                        )}

                        {/* Loading placeholder for initial generation dialogue wait */}
                        {!panel.dialogue && panel.isLoading && !page.pageImageUrl && (
                             <div className="w-1/2 h-8 bg-gray-200/50 rounded self-center animate-pulse mb-4" />
                        )}
                    </div>
                ))}
            </div>

            {/* Loading Overlay (if failure or still processing) */}
            {!page.pageImageUrl && !page.panels[0].isLoading && (
                 <div className="absolute inset-0 flex items-center justify-center bg-gray-100 z-20">
                     <span className="text-red-500 font-bold">Görsel Yüklenemedi</span>
                 </div>
            )}
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { ComicConfig, ComicPanelData, Character } from "../types";

// Initialize the client
// The API key is injected automatically via process.env.API_KEY
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const STORY_MODEL = "gemini-3-flash-preview";
const IMAGE_MODEL = "gemini-2.5-flash-image";

/**
 * Generates an avatar image for a character using a specific Character Sheet template.
 */
export const generateCharacterAvatar = async (
  name: string,
  description: string,
  style: string
): Promise<string> => {
  try {
    // Updated prompt for a structured Character Reference Sheet
    const prompt = `
      Character Design Reference Sheet for ${name}.
      Layout: Structured Character Template.

      Visual Elements Required:
      1. LEFT SIDE: A detailed Full Body shot showing the character's outfit, physique, and stance.
      2. RIGHT SIDE (Top): A Close-up Portrait (Headshot) focusing on facial features and expression.
      3. RIGHT SIDE (Bottom): A stylized text block listing 'Name' and 'Attributes' (as aesthetic visual elements).

      Character Details: ${description}.
      Art Style: ${style}.
      Background: Clean, neutral or white studio background. Professional concept art style.
    `;

    const response = await ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: prompt,
    });

    let base64Image = "";
    const parts = response.candidates?.[0]?.content?.parts;

    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          base64Image = part.inlineData.data;
          break;
        }
      }
    }

    if (!base64Image) return "";
    return `data:image/png;base64,${base64Image}`;
  } catch (error) {
    console.error("Avatar generation error:", error);
    return "";
  }
};

/**
 * Generates a random comic configuration (Topic, Intro, Cast).
 */
export const generateRandomComicConfig = async (): Promise<Partial<ComicConfig>> => {
    const prompt = `
      Generate a creative, unique, and exciting comic book concept in Turkish.

      Output JSON format:
      {
        "topic": "A short, catchy title/topic",
        "intro": "An engaging opening paragraph setting the scene (2-3 sentences)",
        "style": "One of: 'Classic Comic Book', 'Manga', 'Noir', 'Cyberpunk', 'Watercolor'",
        "cast": [
          { "name": "Character Name", "description": "Visual description (clothing, hair, distinct features)" },
          { "name": "Character Name", "description": "Visual description" }
        ]
      }

      Generate 2 or 3 distinct characters.
    `;

    const responseSchema: Schema = {
      type: Type.OBJECT,
      properties: {
        topic: { type: Type.STRING },
        intro: { type: Type.STRING },
        style: { type: Type.STRING },
        cast: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING },
            },
            required: ["name", "description"]
          }
        }
      },
      required: ["topic", "intro", "style", "cast"]
    };

    try {
      const response = await ai.models.generateContent({
        model: STORY_MODEL,
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: responseSchema,
        },
      });

      const text = response.text;
      if (!text) throw new Error("No config generated");

      const data = JSON.parse(text);

      // Add IDs to characters
      const castWithIds = data.cast.map((c: any) => ({
          ...c,
          id: crypto.randomUUID(),
      }));

      return {
          ...data,
          cast: castWithIds
      };
    } catch (error) {
      console.error("Random config generation error:", error);
      throw error;
    }
  };

/**
 * Generates the script/storyboard for the next 4 panels based on inputs.
 */
export const generateComicScript = async (
  config: ComicConfig,
  history: string[],
  userDirection: string = ""
): Promise<ComicPanelData[]> => {
  const castDescription = config.cast
    .map((c) => `${c.name} (${c.description})`)
    .join(", ");

  const previousContext = history.length > 0 ? history.join("\n") : "None yet.";

  const directionPrompt = userDirection 
    ? `IMPORTANT USER DIRECTION FOR THIS PAGE: ${userDirection}` 
    : "Continue the story logically from previous events.";

  const prompt = `
    You are a professional comic book writer.
    Topic: ${config.topic}
    Cast: ${castDescription}
    Story Start/Context: ${config.intro}
    Previous Events: ${previousContext}

    ${directionPrompt}

    Task: Write the script for the NEXT 4 panels of this comic.

    For each panel, provide:
    1. 'imagePrompt': A highly detailed visual description of the scene. Include character appearance, action, setting, and lighting. Describe it as a comic book panel style. ALWAYS include the character names clearly in the prompt if they appear.
    2. 'dialogue': The text spoken by characters or a narrator caption. Keep it brief.
  `;

  const responseSchema: Schema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        imagePrompt: {
          type: Type.STRING,
          description: "Visual description for image generation",
        },
        dialogue: {
          type: Type.STRING,
          description: "Dialogue or caption text",
        },
      },
      required: ["imagePrompt", "dialogue"],
    },
  };

  try {
    const response = await ai.models.generateContent({
      model: STORY_MODEL,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        systemInstruction: "You are a comic book creator. Generate exciting and consistent storyboards.",
      },
    });

    const text = response.text;
    if (!text) throw new Error("No script generated");

    return JSON.parse(text) as ComicPanelData[];
  } catch (error) {
    console.error("Script generation error:", error);
    throw error;
  }
};

/**
 * Generates a SINGLE full-page image containing a 2x2 grid of panels.
 * This saves quota by making 1 API call instead of 4.
 */
export const generateFullPageImage = async (
  panels: ComicPanelData[],
  style: string,
  cast: Character[]
): Promise<string> => {
  try {
    const parts: any[] = [];

    // 1. Construct a master prompt that describes the 2x2 layout
    let layoutDescription = `
      Create a full Comic Book Page with a STRICT 2x2 GRID LAYOUT (4 panels total).
      Art Style: ${style}.
      Quality: High definition, vibrant colors, clean thick panel borders (gutters).

      STRICT PLACEMENT RULES:
      1. ONLY draw characters if they are explicitly named in the description for that specific panel.
      2. If a panel description describes a landscape or object, DO NOT insert characters.
      3. Do not bleed characters from one panel to another.

      Content:
    `;

    panels.forEach((p, i) => {
        const position = i === 0 ? "Top-Left" : i === 1 ? "Top-Right" : i === 2 ? "Bottom-Left" : "Bottom-Right";
        layoutDescription += `\nPANEL ${i+1} (${position}): ${p.imagePrompt}`;
    });

    // 2. Identify all characters present in the entire page for reference
    const uniqueCharactersInPage = new Set<string>();
    panels.forEach(p => {
        cast.forEach(c => {
            if (p.imagePrompt.toLowerCase().includes(c.name.toLowerCase())) {
                uniqueCharactersInPage.add(c.id);
            }
        });
    });

    // 3. Add reference images for consistent characters
    const matchedCharacters = cast.filter(c => uniqueCharactersInPage.has(c.id) && c.avatarUrl);

    let referenceInstructions = "";
    if (matchedCharacters.length > 0) {
        referenceInstructions = "\n\nREFERENCE LIBRARY: I have provided reference images for the following characters: " + matchedCharacters.map(c => c.name).join(", ") + ". USE THESE REFERENCES TO DRAW THE CHARACTERS CORRECTLY, BUT ONLY DRAW THEM IN THE PANELS WHERE THEIR NAME APPEARS IN THE TEXT.";

        for (const char of matchedCharacters) {
            if (char.avatarUrl) {
                // Remove the data URL prefix to get raw base64
                const base64Data = char.avatarUrl.split(',')[1];
                parts.push({
                    inlineData: {
                        data: base64Data,
                        mimeType: "image/png"
                    }
                });
            }
        }
    }

    const finalPrompt = `${layoutDescription} ${referenceInstructions}`;

    // Add text prompt as the last part
    parts.push({ text: finalPrompt });

    const response = await ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: { parts: parts },
      config: {
          aspectRatio: "1:1", // Square page for 2x2 grid
          imageSize: "1K" // Standard resolution is fine
      }
    });

    // Extract image
    let base64Image = "";
    const resParts = response.candidates?.[0]?.content?.parts;

    if (resParts) {
      for (const part of resParts) {
        if (part.inlineData && part.inlineData.data) {
          base64Image = part.inlineData.data;
          break;
        }
      }
    }

    if (!base64Image) {
        console.warn("No image data found in response.");
        return ""; 
    }

    return `data:image/png;base64,${base64Image}`;
  } catch (error) {
    console.error("Image generation error:", error);
    return ""; 
  }
};

/**
 * Generates a SINGLE image for a specific panel.
 * Used for regenerating a specific panel if the user is not satisfied.
 */
export const generateSinglePanelImage = async (
  panelPrompt: string,
  style: string,
  cast: Character[]
): Promise<string> => {
  try {
    const parts: any[] = [];

    // Check for characters in this specific panel
    const matchedCharacters = cast.filter(c => 
        panelPrompt.toLowerCase().includes(c.name.toLowerCase()) && c.avatarUrl
    );

    let referenceInstructions = "";
    if (matchedCharacters.length > 0) {
        referenceInstructions = " IMPORTANT: Maintain exact character consistency (face, hair, clothing) for: " + matchedCharacters.map(c => c.name).join(", ") + " using the attached references.";

        for (const char of matchedCharacters) {
             const base64Data = char.avatarUrl!.split(',')[1];
             parts.push({
                inlineData: {
                    data: base64Data,
                    mimeType: "image/png"
                }
             });
        }
    }

    const finalPrompt = `Comic book panel, ${style} style. ${panelPrompt}.${referenceInstructions} High quality, vibrant colors, clear outlines, dynamic composition.`;

    parts.push({ text: finalPrompt });

    const response = await ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: { parts: parts },
      config: {
        aspectRatio: "1:1",
        imageSize: "1K"
      }
    });

    let base64Image = "";
    const resParts = response.candidates?.[0]?.content?.parts;

    if (resParts) {
      for (const part of resParts) {
        if (part.inlineData && part.inlineData.data) {
          base64Image = part.inlineData.data;
          break;
        }
      }
    }

    if (!base64Image) return "";
    return `data:image/png;base64,${base64Image}`;
  } catch (error) {
    console.error("Single panel generation error:", error);
    return "";
  }
};

import React, { useState } from "react";
import { Plus, Trash2, BookOpen, User, Play, Loader2, Sparkles, X, ChevronLeft, Dices } from "lucide-react";
import { Character, ComicConfig, GeneratorStatus } from "../types";
import { generateCharacterAvatar } from "../services/geminiService";

interface SidebarProps {
  config: ComicConfig;
  setConfig: React.Dispatch<React.SetStateAction<ComicConfig>>;
  onGenerate: () => void;
  onAutoFill: () => void;
  status: GeneratorStatus;
  isOpen: boolean;
  onToggle: () => void;
  isAutoFilling?: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({
  config,
  setConfig,
  onGenerate,
  onAutoFill,
  status,
  isOpen,
  onToggle,
  isAutoFilling = false
}) => {
  const [newCharName, setNewCharName] = useState("");
  const [newCharDesc, setNewCharDesc] = useState("");
  const [isGeneratingAvatar, setIsGeneratingAvatar] = useState(false);
  const [previewImage, setPreviewImage] = useState<string | null>(null);

  const handleAddCharacter = async () => {
    if (!newCharName.trim()) return;

    setIsGeneratingAvatar(true);

    try {
        // Generate avatar immediately
        const avatarUrl = await generateCharacterAvatar(newCharName, newCharDesc, config.style);

        const newChar: Character = {
            id: crypto.randomUUID(),
            name: newCharName,
            description: newCharDesc || "Generic appearance",
            avatarUrl: avatarUrl
        };

        setConfig((prev) => ({ ...prev, cast: [...prev.cast, newChar] }));
        setNewCharName("");
        setNewCharDesc("");
    } catch (e) {
        console.error("Avatar error", e);
        // Add without avatar if fails
        const newChar: Character = {
            id: crypto.randomUUID(),
            name: newCharName,
            description: newCharDesc || "Generic appearance",
        };
        setConfig((prev) => ({ ...prev, cast: [...prev.cast, newChar] }));
    } finally {
        setIsGeneratingAvatar(false);
    }
  };

  const handleRemoveCharacter = (id: string) => {
    setConfig((prev) => ({
      ...prev,
      cast: prev.cast.filter((c) => c.id !== id),
    }));
  };

  const isLoading = status !== GeneratorStatus.IDLE && status !== GeneratorStatus.COMPLETE && status !== GeneratorStatus.ERROR;

  return (
    <>
      <aside 
        className={`
            fixed inset-y-0 left-0 z-40 h-screen bg-gray-900 text-gray-100 flex flex-col border-r border-gray-800 shadow-2xl transition-all duration-300 ease-in-out
            ${isOpen ? "translate-x-0" : "-translate-x-full"} 
            md:relative md:translate-x-0 
            ${isOpen ? "md:w-80" : "md:w-0 md:overflow-hidden md:border-none"}
        `}
      >
        <div className={`flex flex-col h-full ${!isOpen && "md:invisible"}`}> 
            {/* Added invisible wrapper for desktop animation smoothness */}
            <div className="p-6 flex items-center justify-between">
            <h1 className="text-2xl font-bold bg-gradient-to-r from-yellow-400 to-orange-500 bg-clip-text text-transparent flex items-center gap-2 whitespace-nowrap">
                <BookOpen className="text-yellow-400" />
                ComicGen AI
            </h1>
            <button 
                onClick={onToggle}
                className="p-1 hover:bg-gray-800 rounded-full text-gray-400 hover:text-white transition-colors"
            >
                <ChevronLeft size={20} />
            </button>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar px-6 pb-6">

                {/* Auto Fill Button */}
                <button
                    onClick={onAutoFill}
                    disabled={isAutoFilling || isLoading}
                    className="w-full mb-6 py-2 px-3 bg-gradient-to-r from-purple-600 to-blue-600 hover:from-purple-500 hover:to-blue-500 rounded text-sm font-bold flex items-center justify-center gap-2 transition-all shadow-md hover:shadow-lg disabled:opacity-50"
                >
                    {isAutoFilling ? (
                         <Loader2 size={16} className="animate-spin" />
                    ) : (
                         <Dices size={16} />
                    )}
                    Rastgele Doldur
                </button>

                {/* Topic Section */}
                <div className="mb-6 space-y-2">
                    <label className="text-xs font-semibold text-gray-400 uppercase tracking-wider whitespace-nowrap">
                        Çizgi Roman Konusu
                    </label>
                    <textarea
                        className="w-full bg-gray-800 border border-gray-700 rounded p-3 text-sm focus:ring-2 focus:ring-yellow-500 outline-none resize-none h-20"
                        placeholder="Örn: Uzayda geçen bir kovboy hikayesi..."
                        value={config.topic}
                        onChange={(e) =>
                        setConfig((prev) => ({ ...prev, topic: e.target.value }))
                        }
                    />
                </div>

                {/* Intro Section */}
                <div className="mb-6 space-y-2">
                    <label className="text-xs font-semibold text-gray-400 uppercase tracking-wider whitespace-nowrap">
                        Hikaye Girişi
                    </label>
                    <textarea
                        className="w-full bg-gray-800 border border-gray-700 rounded p-3 text-sm focus:ring-2 focus:ring-yellow-500 outline-none resize-none h-24"
                        placeholder="Hikaye nasıl başlıyor?..."
                        value={config.intro}
                        onChange={(e) =>
                        setConfig((prev) => ({ ...prev, intro: e.target.value }))
                        }
                    />
                </div>

                {/* Style Section */}
                <div className="mb-6 space-y-2">
                    <label className="text-xs font-semibold text-gray-400 uppercase tracking-wider whitespace-nowrap">
                        Görsel Stil
                    </label>
                    <select
                        className="w-full bg-gray-800 border border-gray-700 rounded p-2 text-sm focus:ring-2 focus:ring-yellow-500 outline-none"
                        value={config.style}
                        onChange={(e) => setConfig(prev => ({ ...prev, style: e.target.value }))}
                    >
                        <option value="Classic Comic Book">Klasik Çizgi Roman</option>
                        <option value="Manga">Manga / Anime</option>
                        <option value="Noir">Noir / Siyah Beyaz</option>
                        <option value="Cyberpunk">Cyberpunk</option>
                        <option value="Watercolor">Sulu Boya</option>
                    </select>
                </div>

                {/* Cast Section */}
                <div className="mb-6">
                    <div className="flex justify-between items-center mb-2">
                        <label className="text-xs font-semibold text-gray-400 uppercase tracking-wider whitespace-nowrap">
                        Cast Kadrosu
                        </label>
                        <span className="text-xs text-gray-500">{config.cast.length} Karakter</span>
                    </div>

                    <div className="bg-gray-800 rounded-lg p-3 space-y-3 mb-3 border border-gray-700">
                        <div className="space-y-2">
                        <input
                            type="text"
                            placeholder="İsim (Örn: Dedektif John)"
                            className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-xs focus:border-yellow-500 outline-none"
                            value={newCharName}
                            onChange={(e) => setNewCharName(e.target.value)}
