  // Auto-scroll to bottom when new pages are added
  useEffect(() => {
    if (pages.length > 0) {
      bottomRef.current?.scrollIntoView({ behavior: "smooth" });
    }
  }, [pages.length, status]);

  // Initial Responsive Sidebar Check
  useEffect(() => {
    const handleResize = () => {
        if (window.innerWidth < 768) {
            setIsSidebarOpen(false);
        } else {
            setIsSidebarOpen(true);
        }
    };
    // Set initial state based on current width (only on mount)
    if (window.innerWidth < 768) setIsSidebarOpen(false);

    // Optional: Auto-close on resize to mobile could be annoying, so we just set initial.
  }, []);

  const handleAutoFill = async () => {
    setIsAutoFilling(true);
    try {
        const randomConfig = await generateRandomComicConfig();

        // Update config with text data first
        if (randomConfig.cast && randomConfig.topic && randomConfig.intro && randomConfig.style) {
             const newConfig = {
                 ...config,
                 topic: randomConfig.topic,
                 intro: randomConfig.intro,
                 style: randomConfig.style,
                 cast: randomConfig.cast as Character[]
             };
             setConfig(newConfig);

             // Now trigger avatar generation in background for each character
             // We use a local variable to update state progressively
             const castToProcess = [...(randomConfig.cast as Character[])];

             // Process sequentially to avoid rate limits (optional, but safer)
             for (let i = 0; i < castToProcess.length; i++) {
                 const char = castToProcess[i];
                 try {
                     const avatarUrl = await generateCharacterAvatar(char.name, char.description, randomConfig.style || "Classic Comic Book");

                     // Update state with the new avatar
                     setConfig(prev => ({
                         ...prev,
                         cast: prev.cast.map(c => c.id === char.id ? { ...c, avatarUrl } : c)
                     }));
                 } catch (e) {
                     console.error(`Failed to generate avatar for ${char.name}`, e);
                 }
             }
        }
    } catch (e) {
        console.error("Auto fill failed", e);
        alert("Rastgele hikaye oluşturulurken bir hata oluştu.");
    } finally {
        setIsAutoFilling(false);
    }
  };

  const handleStartGeneration = async () => {
     // Close sidebar on mobile when generation starts to see content
     if (window.innerWidth < 768) {
         setIsSidebarOpen(false);
     }
     // Initial start doesn't need a specific next-page prompt, uses intro
     await performGeneration("");
  };

  const handleNextPageClick = () => {
    setUserDirection("");
    setShowNextPageModal(true);
  };

  const confirmNextPageGeneration = () => {
    setShowNextPageModal(false);
    performGeneration(userDirection);
  };

  const performGeneration = async (direction: string) => {
    if (status !== GeneratorStatus.IDLE && status !== GeneratorStatus.COMPLETE && status !== GeneratorStatus.ERROR) return;

    try {
      setStatus(GeneratorStatus.GENERATING_STORY);

      // Create a skeleton page
      const newPageId = crypto.randomUUID();
      const skeletonPanels: ComicPanelData[] = Array(4).fill({
        imagePrompt: "",
        dialogue: "",
        isLoading: true,
      });

      const newPage: ComicPage = {
        id: newPageId,
        panels: skeletonPanels,
      };

      setPages((prev) => [...prev, newPage]);

      // 1. Generate Script
      // Collect dialogue history for context
      const history = pages.flatMap(p => p.panels.map(panel => panel.dialogue));
      const scriptPanels = await generateComicScript(config, history, direction);

      // Update page with text, keep loading spinners
      setPages((prev) =>
        prev.map((p) =>
          p.id === newPageId
            ? {
                ...p,
                panels: scriptPanels.map((sp) => ({
                  ...sp,
                  isLoading: true, // still loading image
                })),
              }
            : p
        )
      );

      setStatus(GeneratorStatus.GENERATING_IMAGES);

      // 2. Generate Single Full Page Image (Saves Quota)
      // Pass config.cast so the service can use avatars as reference
      const fullPageImageUrl = await generateFullPageImage(scriptPanels, config.style, config.cast);

      // Update state with single image and remove loading
      setPages((prev) =>
        prev.map((p) =>
          p.id === newPageId
            ? {
                ...p,
                pageImageUrl: fullPageImageUrl,
                panels: p.panels.map((panel) => ({
                  ...panel,
                  isLoading: false,
                })),
              }
            : p
        )
      );

      setStatus(GeneratorStatus.COMPLETE);
    } catch (error) {
      console.error("Generation failed", error);
      setStatus(GeneratorStatus.ERROR);
      // Remove the skeleton page if it failed completely during script generation
      if (status === GeneratorStatus.GENERATING_STORY) {
         setPages(prev => prev.slice(0, -1));
      }
    }
  };

  const handleRegeneratePanel = async (pageId: string, panelIndex: number) => {
      const page = pages.find(p => p.id === pageId);
      if (!page) return;

      const panel = page.panels[panelIndex];
      if (!panel) return;

      // Set loading state for specific panel
      setPages(prev => prev.map(p => {
          if (p.id !== pageId) return p;
          const newPanels = [...p.panels];
          newPanels[panelIndex] = { ...newPanels[panelIndex], isLoading: true };
          return { ...p, panels: newPanels };
      }));

      try {
          const newImageUrl = await generateSinglePanelImage(panel.imagePrompt, config.style, config.cast);

          setPages(prev => prev.map(p => {
            if (p.id !== pageId) return p;
            const newPanels = [...p.panels];
            newPanels[panelIndex] = { ...newPanels[panelIndex], isLoading: false, imageUrl: newImageUrl };
            return { ...p, panels: newPanels };
        }));

      } catch (error) {
          console.error("Panel regeneration failed", error);
          // Revert loading state
          setPages(prev => prev.map(p => {
            if (p.id !== pageId) return p;
            const newPanels = [...p.panels];
            newPanels[panelIndex] = { ...newPanels[panelIndex], isLoading: false };
            return { ...p, panels: newPanels };
        }));
      }
  };

  return (
    <div className="flex flex-col md:flex-row min-h-screen bg-gray-100 font-sans relative overflow-hidden">
      {/* Left Sidebar */}
      <Sidebar
        config={config}
        setConfig={setConfig}
        onGenerate={handleStartGeneration}
        onAutoFill={handleAutoFill}
        status={status}
        isOpen={isSidebarOpen}
        onToggle={() => setIsSidebarOpen(!isSidebarOpen)}
        isAutoFilling={isAutoFilling}
      />

      {/* Mobile Sidebar Backdrop */}
      {isSidebarOpen && (
          <div 
            className="fixed inset-0 bg-black/50 z-30 md:hidden" 
            onClick={() => setIsSidebarOpen(false)}
          />
      )}

      {/* Toggle Button (Visible when closed) */}
      {!isSidebarOpen && (
        <button
          onClick={() => setIsSidebarOpen(true)}
          className="fixed top-4 left-4 z-20 p-2 bg-yellow-500 rounded-lg shadow-lg hover:bg-yellow-400 text-gray-900 transition-colors border-2 border-black"
          aria-label="Open Menu"
        >
          <Menu size={24} />
        </button>
      )}

      {/* Main Content Area */}
      <main className="flex-1 h-screen overflow-y-auto bg-slate-200 relative custom-scrollbar">
        {/* Background Pattern */}
        <div className="absolute inset-0 opacity-5 pointer-events-none" 
             style={{ 
               backgroundImage: 'radial-gradient(circle, #000 1px, transparent 1px)', 
               backgroundSize: '20px 20px' 
             }} 
        />

        <div className="max-w-5xl mx-auto px-4 py-8 relative z-10 min-h-full flex flex-col">

          {/* Header Spacer for Toggle Button when visible */}
          {!isSidebarOpen && <div className="h-12 md:h-0" />}

          {/* Empty State */}
          {pages.length === 0 && (
            <div className="flex-1 flex flex-col items-center justify-center text-center text-gray-500 opacity-60">
              <Ghost size={64} className="mb-4 text-gray-400" />
              <h2 className="text-2xl font-bold text-gray-600 mb-2">Hikaye Başlamadı</h2>
              <p className="max-w-md mb-8">Soldaki menüyü açarak karakterleri ekleyin veya aşağıdan rastgele bir hikaye başlatın.</p>

              <button
                onClick={handleAutoFill}
                disabled={isAutoFilling}
                className="bg-white border-4 border-black text-black font-display text-xl px-8 py-4 rounded-xl shadow-[8px_8px_0px_#000] hover:-translate-y-1 hover:shadow-[12px_12px_0px_#000] transition-all flex items-center gap-3 disabled:opacity-50 disabled:hover:translate-y-0"
              >
                  {isAutoFilling ? (
                      <Loader2 className="animate-spin" size={24} />
                  ) : (
                      <Sparkles className="text-yellow-500" size={24} />
                  )}
                  Rastgele Hikaye Başlat
              </button>
            </div>
          )}

          {/* Comic Pages */}
          <div className="space-y-8 pb-32">
            {pages.map((page, index) => (
              <ComicPageDisplay 
                key={page.id} 
                page={page} 
                pageIndex={index} 
                onPanelClick={(url) => setPreviewImage(url)}
                onRegeneratePanel={(panelIndex) => handleRegeneratePanel(page.id, panelIndex)}
              />
            ))}

            {/* Error State */}
            {status === GeneratorStatus.ERROR && (
              <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 rounded shadow-sm mx-auto max-w-lg">
                <p className="font-bold">Bir hata oluştu</p>
                <p>İçerik üretilirken bir sorun yaşandı. Lütfen tekrar deneyin.</p>
              </div>
            )}

            <div ref={bottomRef} />
          </div>
        </div>

        {/* Floating Action Button (Only visible if we have pages and not generating) */}
        {pages.length > 0 && status === GeneratorStatus.COMPLETE && (
            <div className="fixed bottom-8 right-8 z-20">
                <button 
                    onClick={handleNextPageClick}
                    className="bg-yellow-500 hover:bg-yellow-400 text-black border-2 border-black font-bold py-3 px-6 rounded-full shadow-[4px_4px_0px_rgba(0,0,0,1)] flex items-center gap-2 hover:-translate-y-1 transition-transform"
                >
                    <PlusCircle size={24} />
                    Sonraki Sayfayı Çiz
                </button>
            </div>
        )}

        {/* User Direction Modal */}
        {showNextPageModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden border-4 border-black animate-in fade-in zoom-in duration-200">
               <div className="bg-yellow-400 p-4 border-b-4 border-black flex justify-between items-center">
                  <h3 className="font-display text-xl uppercase tracking-wider text-black">Devam Et</h3>
                  <button onClick={() => setShowNextPageModal(false)} className="text-black hover:text-white transition-colors">
                    <X size={24} />
                  </button>
               </div>
               <div className="p-6">
                 <label className="block text-sm font-bold text-gray-700 mb-2 font-comic uppercase">
                    Bu bölümde ne olsun?
                 </label>
                 <textarea 
                    className="w-full h-32 bg-gray-100 border-2 border-gray-300 rounded p-4 text-gray-800 focus:border-yellow-500 focus:ring-0 outline-none resize-none font-comic text-lg"
                    placeholder="Örn: Kahramanlar gizli geçidi bulur ama tuzak çalışır..."
                    value={userDirection}
                    onChange={(e) => setUserDirection(e.target.value)}
                    autoFocus
                 />
                 <p className="text-xs text-gray-500 mt-2">
                   * Boş bırakırsanız yapay zeka hikayeyi kendi kurgusuna göre devam ettirir.
                 </p>
               </div>
               <div className="bg-gray-100 p-4 border-t-2 border-gray-200 flex justify-end gap-3">
                  <button 
                    onClick={() => setShowNextPageModal(false)}
                    className="px-4 py-2 font-bold text-gray-500 hover:text-black transition-colors"
                  >
                    İptal
                  </button>
                  <button 
                    onClick={confirmNextPageGeneration}
                    className="px-6 py-2 bg-black text-white font-bold rounded hover:bg-gray-800 transition-colors flex items-center gap-2 shadow-[2px_2px_0px_#fbbf24]"
                  >
                    <Send size={16} />
                    Oluştur
                  </button>
               </div>
            </div>
          </div>
        )}

        {/* Global Image Preview Modal */}
        {previewImage && (
          <div 
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/95 p-4 backdrop-blur-md animate-in fade-in duration-200"
            onClick={() => setPreviewImage(null)}
          >
            <div className="relative max-w-5xl w-full max-h-[90vh] flex items-center justify-center">
              <button 
                  onClick={() => setPreviewImage(null)}
                  className="absolute -top-12 right-0 text-white hover:text-yellow-400 transition-colors bg-white/10 p-2 rounded-full"
              >
                  <X size={24} />
              </button>
              <img 
                  src={previewImage} 
                  alt="Full Size Panel" 
                  className="max-w-full max-h-[85vh] object-contain rounded border-4 border-gray-800 shadow-2xl"
                  onClick={(e) => e.stopPropagation()} 
              />
            </div>
          </div>
        )}

      </main>
    </div>
  );
}

import React, { useState } from "react";
import { Plus, Trash2, BookOpen, User, Play, Loader2, Sparkles, X, ChevronLeft, Dices } from "lucide-react";
import { Character, ComicConfig, GeneratorStatus } from "../types";
import { generateCharacterAvatar } from "../services/geminiService";

interface SidebarProps {
  config: ComicConfig;
  setConfig: React.Dispatch<React.SetStateAction<ComicConfig>>;
  onGenerate: () => void;
  onAutoFill: () => void;
  status: GeneratorStatus;
  isOpen: boolean;
  onToggle: () => void;
  isAutoFilling?: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({
  config,
  setConfig,
  onGenerate,
  onAutoFill,
  status,
  isOpen,
  onToggle,
  isAutoFilling = false
}) => {
  const [newCharName, setNewCharName] = useState("");
  const [newCharDesc, setNewCharDesc] = useState("");
  const [isGeneratingAvatar, setIsGeneratingAvatar] = useState(false);
  const [previewImage, setPreviewImage] = useState<string | null>(null);

  const handleAddCharacter = async () => {
    if (!newCharName.trim()) return;

    setIsGeneratingAvatar(true);

    try {
        // Generate avatar immediately
        const avatarUrl = await generateCharacterAvatar(newCharName, newCharDesc, config.style);

        const newChar: Character = {
            id: crypto.randomUUID(),
            name: newCharName,
            description: newCharDesc || "Generic appearance",
            avatarUrl: avatarUrl
        };

        setConfig((prev) => ({ ...prev, cast: [...prev.cast, newChar] }));
        setNewCharName("");
        setNewCharDesc("");
    } catch (e) {
        console.error("Avatar error", e);
        // Add without avatar if fails
        const newChar: Character = {
            id: crypto.randomUUID(),
            name: newCharName,
            description: newCharDesc || "Generic appearance",
        };
        setConfig((prev) => ({ ...prev, cast: [...prev.cast, newChar] }));
    } finally {
        setIsGeneratingAvatar(false);
    }
  };

  const handleRemoveCharacter = (id: string) => {
    setConfig((prev) => ({
      ...prev,
      cast: prev.cast.filter((c) => c.id !== id),
    }));
  };

  const isLoading = status !== GeneratorStatus.IDLE && status !== GeneratorStatus.COMPLETE && status !== GeneratorStatus.ERROR;

  return (
    <>
      <aside 
        className={`
            fixed inset-y-0 left-0 z-40 h-[100dvh] bg-gray-900 text-gray-100 flex flex-col border-r border-gray-800 shadow-2xl transition-all duration-300 ease-in-out
            ${isOpen ? "translate-x-0" : "-translate-x-full"} 
            md:relative md:translate-x-0 
            ${isOpen ? "md:w-80" : "md:w-0 md:overflow-hidden md:border-none"}
        `}
      >
        <div className={`flex flex-col h-full ${!isOpen && "md:invisible"}`}> 
            {/* Added invisible wrapper for desktop animation smoothness */}
            <div className="p-6 flex items-center justify-between flex-shrink-0">
            <h1 className="text-2xl font-bold bg-gradient-to-r from-yellow-400 to-orange-500 bg-clip-text text-transparent flex items-center gap-2 whitespace-nowrap">
                <BookOpen className="text-yellow-400" />
                ComicGen AI
            </h1>
            <button 
                onClick={onToggle}
                className="p-1 hover:bg-gray-800 rounded-full text-gray-400 hover:text-white transition-colors"
            >
                <ChevronLeft size={20} />
            </button>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar px-6 pb-6">

                {/* Auto Fill Button */}
                <button
                    onClick={onAutoFill}
                    disabled={isAutoFilling || isLoading}
                    className="w-full mb-6 py-2 px-3 bg-gradient-to-r from-purple-600 to-blue-600 hover:from-purple-500 hover:to-blue-500 rounded text-sm font-bold flex items-center justify-center gap-2 transition-all shadow-md hover:shadow-lg disabled:opacity-50"
                >
                    {isAutoFilling ? (
                         <Loader2 size={16} className="animate-spin" />
                    ) : (
                         <Dices size={16} />
                    )}
                    Rastgele Doldur
                </button>

                {/* Topic Section */}
                <div className="mb-6 space-y-2">
                    <label className="text-xs font-semibold text-gray-400 uppercase tracking-wider whitespace-nowrap">
                        Çizgi Roman Konusu
                    </label>
                    <textarea
                        className="w-full bg-gray-800 border border-gray-700 rounded p-3 text-sm focus:ring-2 focus:ring-yellow-500 outline-none resize-none h-20"
                        placeholder="Örn: Uzayda geçen bir kovboy hikayesi..."
                        value={config.topic}
                        onChange={(e) =>
                        setConfig((prev) => ({ ...prev, topic: e.target.value }))
                        }
                    />
                </div>

                {/* Intro Section */}
                <div className="mb-6 space-y-2">
                    <label className="text-xs font-semibold text-gray-400 uppercase tracking-wider whitespace-nowrap">
                        Hikaye Girişi
                    </label>
                    <textarea
                        className="w-full bg-gray-800 border border-gray-700 rounded p-3 text-sm focus:ring-2 focus:ring-yellow-500 outline-none resize-none h-24"
                        placeholder="Hikaye nasıl başlıyor?..."
                        value={config.intro}
                        onChange={(e) =>
                        setConfig((prev) => ({ ...prev, intro: e.target.value }))
                        }
                    />
                </div>

                {/* Style Section */}
                <div className="mb-6 space-y-2">
                    <label className="text-xs font-semibold text-gray-400 uppercase tracking-wider whitespace-nowrap">
                        Görsel Stil
                    </label>
                    <select
                        className="w-full bg-gray-800 border border-gray-700 rounded p-2 text-sm focus:ring-2 focus:ring-yellow-500 outline-none"
                        value={config.style}
                        onChange={(e) => setConfig(prev => ({ ...prev, style: e.target.value }))}
                    >
                        <option value="Classic Comic Book">Klasik Çizgi Roman</option>
                        <option value="Manga">Manga / Anime</option>
                        <option value="Noir">Noir / Siyah Beyaz</option>
                        <option value="Cyberpunk">Cyberpunk</option>
                        <option value="Watercolor">Sulu Boya</option>
                    </select>
                </div>

                {/* Cast Section */}
                <div className="mb-6">
                    <div className="flex justify-between items-center mb-2">
                        <label className="text-xs font-semibold text-gray-400 uppercase tracking-wider whitespace-nowrap">
                        Cast Kadrosu
                        </label>
                        <span className="text-xs text-gray-500">{config.cast.length} Karakter</span>
                    </div>

                    <div className="bg-gray-800 rounded-lg p-3 space-y-3 mb-3 border border-gray-700">
                        <div className="space-y-2">
                        <input
                            type="text"
                            placeholder="İsim (Örn: Dedektif John)"
                            className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-xs focus:border-yellow-500 outline-none"
                            value={newCharName}
                            onChange={(e) => setNewCharName(e.target.value)}
                        />
                        <input
                            type="text"
                            placeholder="Görünüm (Örn: Uzun pardesü, şapka)"
                            className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-xs focus:border-yellow-500 outline-none"
                            value={newCharDesc}
                            onChange={(e) => setNewCharDesc(e.target.value)}
                        />
                        <button
                            onClick={handleAddCharacter}
                            disabled={!newCharName.trim() || isGeneratingAvatar}
                            className="w-full bg-gray-700 hover:bg-gray-600 text-white text-xs py-2 rounded flex items-center justify-center gap-1 transition-colors disabled:opacity-50"
                        >
                            {isGeneratingAvatar ? (
                                <>
                                    <Loader2 size={14} className="animate-spin" /> Avatar Oluşturuluyor...
                                </>
                            ) : (
                                <>
                                    <Plus size={14} /> Karakter Ekle
                                </>
                            )}
                        </button>
                        </div>
                    </div>

                    {/* Removed max-h constraint to allow full sidebar scroll */}
                    <div className="space-y-2 pr-1">
                        {config.cast.map((char) => (
                        <div
                            key={char.id}
                            className="flex items-center justify-between bg-gray-800/50 p-2 rounded border border-gray-700 group"
                        >
                            <div className="flex items-center gap-3 overflow-hidden">
                            <div 
                                className="w-12 h-12 rounded-lg bg-gray-700 overflow-hidden flex-shrink-0 border border-gray-600 cursor-pointer hover:border-yellow-400 transition-colors"
                                onClick={() => char.avatarUrl && setPreviewImage(char.avatarUrl)}
                            >
                                {char.avatarUrl ? (
                                    <img src={char.avatarUrl} alt={char.name} className="w-full h-full object-cover" />
                                ) : (
                                    <div className="w-full h-full flex items-center justify-center">
                                        <User size={16} className="text-gray-400" />
                                    </div>
                                )}
                            </div>
                            <div className="min-w-0">
                                <p className="text-sm font-medium text-gray-200 truncate">{char.name}</p>
                                <p className="text-xs text-gray-400 truncate">{char.description}</p>
                            </div>
                            </div>
                            <button
                                onClick={() => handleRemoveCharacter(char.id)}
                                className="text-gray-500 hover:text-red-400 transition-colors p-1"
                            >
                                <Trash2 size={14} />
                            </button>
                        </div>
                        ))}
                        {config.cast.length === 0 && (
                        <p className="text-xs text-gray-500 text-center py-2 italic">
                            Henüz karakter eklenmedi.
                        </p>
                        )}
                    </div>
                </div>
            </div>

            <div className="p-6 mt-auto border-t border-gray-800 bg-gray-900 sticky bottom-0 flex-shrink-0">
            <button
                onClick={onGenerate}
                disabled={isLoading || !config.topic || !config.intro}
                className={`w-full py-4 rounded-xl font-bold text-lg flex items-center justify-center gap-2 shadow-lg transition-all
                ${
                    isLoading
                    ? "bg-gray-700 text-gray-400 cursor-not-allowed"
                    : "bg-yellow-500 hover:bg-yellow-400 text-gray-900 hover:scale-[1.02]"
                }
                `}
            >
                {isLoading ? (
                <>
                    <Loader2 className="animate-spin" />
                    {status === GeneratorStatus.GENERATING_STORY ? "Hikaye Yazılıyor..." : "Çiziliyor..."}
                </>
                ) : (
                <>
                    <Play className="fill-current" />
                    Çizgi Romanı Başlat
                </>
                )}
            </button>
            </div>
        </div>
      </aside>

      {/* Full Screen Image Preview Modal */}
      {previewImage && (
        <div 
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 p-4 backdrop-blur-sm animate-in fade-in duration-200"
          onClick={() => setPreviewImage(null)}
        >
          <div className="relative max-w-2xl w-full">
            <button 
                onClick={() => setPreviewImage(null)}
                className="absolute -top-12 right-0 text-white hover:text-yellow-400 transition-colors"
            >
                <X size={32} />
            </button>
            <img 
                src={previewImage} 
                alt="Character Preview" 
                className="w-full h-auto rounded-lg border-4 border-gray-800 shadow-2xl"
                onClick={(e) => e.stopPropagation()} 
            />
          </div>
        </div>
      )}
    </>
  );
};

import React, { useState, useRef, useEffect } from "react";
import { Sidebar } from "./components/Sidebar";
import { ComicPageDisplay } from "./components/ComicPageDisplay";
import {
  ComicConfig,
  ComicPage,
  GeneratorStatus,
  ComicPanelData,
  Character,
} from "./types";
import { generateComicScript, generateFullPageImage, generateSinglePanelImage, generateRandomComicConfig, generateCharacterAvatar } from "./services/geminiService";
import { PlusCircle, Info, Ghost, X, Send, Menu, Sparkles, Loader2 } from "lucide-react";

export default function App() {
  const [config, setConfig] = useState<ComicConfig>({
    topic: "",
    intro: "",
    cast: [],
    style: "Classic Comic Book"
  });

  const [pages, setPages] = useState<ComicPage[]>([]);
  const [status, setStatus] = useState<GeneratorStatus>(GeneratorStatus.IDLE);
  const [isAutoFilling, setIsAutoFilling] = useState(false);

  // States for Modals
  const [showNextPageModal, setShowNextPageModal] = useState(false);
  const [userDirection, setUserDirection] = useState("");
  const [previewImage, setPreviewImage] = useState<string | null>(null);

  // Sidebar State
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  const bottomRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom when new pages are added
  useEffect(() => {
    if (pages.length > 0) {
      bottomRef.current?.scrollIntoView({ behavior: "smooth" });
    }
  }, [pages.length, status]);

  // Initial Responsive Sidebar Check
  useEffect(() => {
    const handleResize = () => {
        if (window.innerWidth < 768) {
            setIsSidebarOpen(false);
        } else {
            setIsSidebarOpen(true);
        }
    };
    // Set initial state based on current width (only on mount)
    if (window.innerWidth < 768) setIsSidebarOpen(false);

    // Optional: Auto-close on resize to mobile could be annoying, so we just set initial.
  }, []);

  const handleAutoFill = async () => {
    setIsAutoFilling(true);
    try {
        const randomConfig = await generateRandomComicConfig();

        // Update config with text data first
        if (randomConfig.cast && randomConfig.topic && randomConfig.intro && randomConfig.style) {
             const newConfig = {
                 ...config,
                 topic: randomConfig.topic,
                 intro: randomConfig.intro,
                 style: randomConfig.style,
                 cast: randomConfig.cast as Character[]
             };
             setConfig(newConfig);

             // Now trigger avatar generation in background for each character
             const castToProcess = [...(randomConfig.cast as Character[])];

             for (let i = 0; i < castToProcess.length; i++) {
                 const char = castToProcess[i];
                 try {
                     const avatarUrl = await generateCharacterAvatar(char.name, char.description, randomConfig.style || "Classic Comic Book");

                     setConfig(prev => ({
                         ...prev,
                         cast: prev.cast.map(c => c.id === char.id ? { ...c, avatarUrl } : c)
                     }));
                 } catch (e) {
                     console.error(`Failed to generate avatar for ${char.name}`, e);
                 }
             }
        }
    } catch (e) {
        console.error("Auto fill failed", e);
        alert("Rastgele hikaye oluşturulurken bir hata oluştu.");
    } finally {
        setIsAutoFilling(false);
    }
  };

  const handleStartGeneration = async () => {
     if (window.innerWidth < 768) {
         setIsSidebarOpen(false);
     }
     await performGeneration("");
  };

  const handleNextPageClick = () => {
    setUserDirection("");
    setShowNextPageModal(true);
  };

  const confirmNextPageGeneration = () => {
    setShowNextPageModal(false);
    performGeneration(userDirection);
  };

  const performGeneration = async (direction: string) => {
    if (status !== GeneratorStatus.IDLE && status !== GeneratorStatus.COMPLETE && status !== GeneratorStatus.ERROR) return;

    try {
      setStatus(GeneratorStatus.GENERATING_STORY);

      const newPageId = crypto.randomUUID();
      const skeletonPanels: ComicPanelData[] = Array(4).fill({
        imagePrompt: "",
        dialogue: "",
        isLoading: true,
      });

      const newPage: ComicPage = {
        id: newPageId,
        panels: skeletonPanels,
      };

      setPages((prev) => [...prev, newPage]);

      const history = pages.flatMap(p => p.panels.map(panel => panel.dialogue));
      const scriptPanels = await generateComicScript(config, history, direction);

      setPages((prev) =>
        prev.map((p) =>
          p.id === newPageId
            ? {
                ...p,
                panels: scriptPanels.map((sp) => ({
                  ...sp,
                  isLoading: true,
                })),
              }
            : p
        )
      );

      setStatus(GeneratorStatus.GENERATING_IMAGES);

      const fullPageImageUrl = await generateFullPageImage(scriptPanels, config.style, config.cast);

      setPages((prev) =>
        prev.map((p) =>
          p.id === newPageId
            ? {
                ...p,
                pageImageUrl: fullPageImageUrl,
                panels: p.panels.map((panel) => ({
                  ...panel,
                  isLoading: false,
                })),
              }
            : p
        )
      );

      setStatus(GeneratorStatus.COMPLETE);
    } catch (error) {
      console.error("Generation failed", error);
      setStatus(GeneratorStatus.ERROR);
      if (status === GeneratorStatus.GENERATING_STORY) {
         setPages(prev => prev.slice(0, -1));
      }
    }
  };

  const handleRegeneratePanel = async (pageId: string, panelIndex: number) => {
      const page = pages.find(p => p.id === pageId);
      if (!page) return;

      const panel = page.panels[panelIndex];
      if (!panel) return;

      setPages(prev => prev.map(p => {
          if (p.id !== pageId) return p;
          const newPanels = [...p.panels];
          newPanels[panelIndex] = { ...newPanels[panelIndex], isLoading: true };
          return { ...p, panels: newPanels };
      }));

      try {
          const newImageUrl = await generateSinglePanelImage(panel.imagePrompt, config.style, config.cast);

          setPages(prev => prev.map(p => {
            if (p.id !== pageId) return p;
            const newPanels = [...p.panels];
            newPanels[panelIndex] = { ...newPanels[panelIndex], isLoading: false, imageUrl: newImageUrl };
            return { ...p, panels: newPanels };
        }));

      } catch (error) {
          console.error("Panel regeneration failed", error);
          setPages(prev => prev.map(p => {
            if (p.id !== pageId) return p;
            const newPanels = [...p.panels];
            newPanels[panelIndex] = { ...newPanels[panelIndex], isLoading: false };
            return { ...p, panels: newPanels };
        }));
      }
  };

  return (
    <div className="flex flex-col md:flex-row h-screen bg-gray-100 font-sans relative overflow-hidden">
      {/* Left Sidebar */}
      <Sidebar
        config={config}
        setConfig={setConfig}
        onGenerate={handleStartGeneration}
        onAutoFill={handleAutoFill}
        status={status}
        isOpen={isSidebarOpen}
        onToggle={() => setIsSidebarOpen(!isSidebarOpen)}
        isAutoFilling={isAutoFilling}
      />

      {/* Mobile Sidebar Backdrop */}
      {isSidebarOpen && (
          <div 
            className="fixed inset-0 bg-black/50 z-30 md:hidden" 
            onClick={() => setIsSidebarOpen(false)}
          />
      )}

      {/* Toggle Button (Visible when closed) */}
      {!isSidebarOpen && (
        <button
          onClick={() => setIsSidebarOpen(true)}
          className="fixed top-4 left-4 z-20 p-2 bg-yellow-500 rounded-lg shadow-lg hover:bg-yellow-400 text-gray-900 transition-colors border-2 border-black"
          aria-label="Open Menu"
        >
          <Menu size={24} />
        </button>
      )}

      {/* Main Content Area */}
      <main className="flex-1 h-full overflow-y-auto bg-slate-200 relative custom-scrollbar">
        <div className="absolute inset-0 opacity-5 pointer-events-none" 
             style={{ 
               backgroundImage: 'radial-gradient(circle, #000 1px, transparent 1px)', 
               backgroundSize: '20px 20px' 
             }} 
        />

        <div className="max-w-5xl mx-auto px-4 py-8 relative z-10 min-h-full flex flex-col">

          {!isSidebarOpen && <div className="h-12 md:h-0" />}

          {pages.length === 0 && (
            <div className="flex-1 flex flex-col items-center justify-center text-center text-gray-500 opacity-60">
              <Ghost size={64} className="mb-4 text-gray-400" />
              <h2 className="text-2xl font-bold text-gray-600 mb-2">Hikaye Başlamadı</h2>
              <p className="max-w-md mb-8">Soldaki menüyü açarak karakterleri ekleyin veya aşağıdan rastgele bir hikaye başlatın.</p>

              <button
                onClick={handleAutoFill}
                disabled={isAutoFilling}
                className="bg-white border-4 border-black text-black font-display text-xl px-8 py-4 rounded-xl shadow-[8px_8px_0px_#000] hover:-translate-y-1 hover:shadow-[12px_12px_0px_#000] transition-all flex items-center gap-3 disabled:opacity-50 disabled:hover:translate-y-0"
              >
                  {isAutoFilling ? (
                      <Loader2 className="animate-spin" size={24} />
                  ) : (
                      <Sparkles className="text-yellow-500" size={24} />
                  )}
                  Rastgele Hikaye Başlat
              </button>
            </div>
          )}

          <div className="space-y-8 pb-32">
            {pages.map((page, index) => (
              <ComicPageDisplay 
                key={page.id} 
                page={page} 
                pageIndex={index} 
                onPanelClick={(url) => setPreviewImage(url)}
                onRegeneratePanel={(panelIndex) => handleRegeneratePanel(page.id, panelIndex)}
              />
            ))}

            {status === GeneratorStatus.ERROR && (
              <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 rounded shadow-sm mx-auto max-w-lg">
                <p className="font-bold">Bir hata oluştu</p>
                <p>İçerik üretilirken bir sorun yaşandı. Lütfen tekrar deneyin.</p>
              </div>
            )}

            <div ref={bottomRef} />
          </div>
        </div>

        {pages.length > 0 && status === GeneratorStatus.COMPLETE && (
            <div className="fixed bottom-8 right-8 z-20">
                <button 
                    onClick={handleNextPageClick}
                    className="bg-yellow-500 hover:bg-yellow-400 text-black border-2 border-black font-bold py-3 px-6 rounded-full shadow-[4px_4px_0px_rgba(0,0,0,1)] flex items-center gap-2 hover:-translate-y-1 transition-transform"
                >
                    <PlusCircle size={24} />
                    Sonraki Sayfayı Çiz
                </button>
            </div>
        )}

        {showNextPageModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden border-4 border-black animate-in fade-in zoom-in duration-200">
               <div className="bg-yellow-400 p-4 border-b-4 border-black flex justify-between items-center">
                  <h3 className="font-display text-xl uppercase tracking-wider text-black">Devam Et</h3>
                  <button onClick={() => setShowNextPageModal(false)} className="text-black hover:text-white transition-colors">
                    <X size={24} />
                  </button>
               </div>
               <div className="p-6">
                 <label className="block text-sm font-bold text-gray-700 mb-2 font-comic uppercase">
                    Bu bölümde ne olsun?
                 </label>
                 <textarea 
                    className="w-full h-32 bg-gray-100 border-2 border-gray-300 rounded p-4 text-gray-800 focus:border-yellow-500 focus:ring-0 outline-none resize-none font-comic text-lg"
                    placeholder="Örn: Kahramanlar gizli geçidi bulur ama tuzak çalışır..."
                    value={userDirection}
                    onChange={(e) => setUserDirection(e.target.value)}
                    autoFocus
                 />
                 <p className="text-xs text-gray-500 mt-2">
                   * Boş bırakırsanız yapay zeka hikayeyi kendi kurgusuna göre devam ettirir.
                 </p>
               </div>
               <div className="bg-gray-100 p-4 border-t-2 border-gray-200 flex justify-end gap-3">
                  <button 
                    onClick={() => setShowNextPageModal(false)}
                    className="px-4 py-2 font-bold text-gray-500 hover:text-black transition-colors"
                  >
                    İptal
                  </button>
                  <button 
                    onClick={confirmNextPageGeneration}
                    className="px-6 py-2 bg-black text-white font-bold rounded hover:bg-gray-800 transition-colors flex items-center gap-2 shadow-[2px_2px_0px_#fbbf24]"
                  >
                    <Send size={16} />
                    Oluştur
                  </button>
               </div>
            </div>
          </div>
        )}

        {previewImage && (
          <div 
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/95 p-4 backdrop-blur-md animate-in fade-in duration-200"
            onClick={() => setPreviewImage(null)}
          >
            <div className="relative max-w-5xl w-full max-h-[90vh] flex items-center justify-center">
              <button 
                  onClick={() => setPreviewImage(null)}
                  className="absolute -top-12 right-0 text-white hover:text-yellow-400 transition-colors bg-white/10 p-2 rounded-full"
              >
                  <X size={24} />
              </button>
              <img 
                  src={previewImage} 
                  alt="Full Size Panel" 
                  className="max-w-full max-h-[85vh] object-contain rounded border-4 border-gray-800 shadow-2xl"
                  onClick={(e) => e.stopPropagation()} 
              />
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

import React, { useState } from "react";
import { Plus, Trash2, BookOpen, User, Play, Loader2, Sparkles, X, ChevronLeft, Dices } from "lucide-react";
import { Character, ComicConfig, GeneratorStatus } from "../types";
import { generateCharacterAvatar } from "../services/geminiService";

interface SidebarProps {
  config: ComicConfig;
  setConfig: React.Dispatch<React.SetStateAction<ComicConfig>>;
  onGenerate: () => void;
  onAutoFill: () => void;
  status: GeneratorStatus;
  isOpen: boolean;
  onToggle: () => void;
  isAutoFilling?: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({
  config,
  setConfig,
  onGenerate,
  onAutoFill,
  status,
  isOpen,
  onToggle,
  isAutoFilling = false
}) => {
  const [newCharName, setNewCharName] = useState("");
  const [newCharDesc, setNewCharDesc] = useState("");
  const [isGeneratingAvatar, setIsGeneratingAvatar] = useState(false);
  const [previewImage, setPreviewImage] = useState<string | null>(null);

  const handleAddCharacter = async () => {
    if (!newCharName.trim()) return;

    setIsGeneratingAvatar(true);

    try {
        const avatarUrl = await generateCharacterAvatar(newCharName, newCharDesc, config.style);

        const newChar: Character = {
            id: crypto.randomUUID(),
            name: newCharName,
            description: newCharDesc || "Generic appearance",
            avatarUrl: avatarUrl
        };

        setConfig((prev) => ({ ...prev, cast: [...prev.cast, newChar] }));
        setNewCharName("");
        setNewCharDesc("");
    } catch (e) {
        console.error("Avatar error", e);
        const newChar: Character = {
            id: crypto.randomUUID(),
            name: newCharName,
            description: newCharDesc || "Generic appearance",
        };
        setConfig((prev) => ({ ...prev, cast: [...prev.cast, newChar] }));
    } finally {
        setIsGeneratingAvatar(false);
    }
  };

  const handleRemoveCharacter = (id: string) => {
    setConfig((prev) => ({
      ...prev,
      cast: prev.cast.filter((c) => c.id !== id),
    }));
  };

  const isLoading = status !== GeneratorStatus.IDLE && status !== GeneratorStatus.COMPLETE && status !== GeneratorStatus.ERROR;

  return (
    <>
      <aside 
        className={`
            fixed inset-y-0 left-0 z-40 h-[100dvh] bg-gray-900 text-gray-100 flex flex-col border-r border-gray-800 shadow-2xl transition-all duration-300 ease-in-out
            ${isOpen ? "translate-x-0" : "-translate-x-full"} 
            md:relative md:translate-x-0 
            ${isOpen ? "md:w-72" : "md:w-0 md:overflow-hidden md:border-none"}
        `}
      >
        <div className={`flex flex-col h-full ${!isOpen && "md:invisible"}`}> 
            {/* Header */}
            <div className="p-4 flex items-center justify-between flex-shrink-0">
                <h1 className="text-xl font-bold bg-gradient-to-r from-yellow-400 to-orange-500 bg-clip-text text-transparent flex items-center gap-2 whitespace-nowrap">
                    <BookOpen className="text-yellow-400" size={20} />
                    ComicGen AI
                </h1>
                <button 
                    onClick={onToggle}
                    className="p-1 hover:bg-gray-800 rounded-full text-gray-400 hover:text-white transition-colors"
                >
                    <ChevronLeft size={18} />
                </button>
            </div>

            {/* Scrollable Form Content */}
            <div className="flex-1 overflow-y-auto custom-scrollbar px-4 pb-4">

                {/* Auto Fill Button */}
                <button
                    onClick={onAutoFill}
                    disabled={isAutoFilling || isLoading}
                    className="w-full mb-4 py-2 px-3 bg-gradient-to-r from-purple-600 to-blue-600 hover:from-purple-500 hover:to-blue-500 rounded text-xs font-bold flex items-center justify-center gap-2 transition-all shadow-md hover:shadow-lg disabled:opacity-50"
                >
                    {isAutoFilling ? (
                         <Loader2 size={14} className="animate-spin" />
                    ) : (
                         <Dices size={14} />
                    )}
                    Rastgele Doldur
                </button>

                {/* Topic Section */}
                <div className="mb-4 space-y-1">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest whitespace-nowrap">
                        Çizgi Roman Konusu
                    </label>
                    <textarea
                        className="w-full bg-gray-800 border border-gray-700 rounded p-2 text-xs focus:ring-1 focus:ring-yellow-500 outline-none resize-none h-14"
                        placeholder="Örn: Uzayda geçen bir kovboy hikayesi..."
                        value={config.topic}
                        onChange={(e) =>
                            setConfig((prev) => ({ ...prev, topic: e.target.value }))
                        }
                    />
                </div>

                {/* Intro Section */}
                <div className="mb-4 space-y-1">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest whitespace-nowrap">
                        Hikaye Girişi
                    </label>
                    <textarea
                        className="w-full bg-gray-800 border border-gray-700 rounded p-2 text-xs focus:ring-1 focus:ring-yellow-500 outline-none resize-none h-20"
                        placeholder="Hikaye nasıl başlıyor?..."
                        value={config.intro}
                        onChange={(e) =>
                            setConfig((prev) => ({ ...prev, intro: e.target.value }))
                        }
                    />
                </div>

                {/* Style Section */}
                <div className="mb-4 space-y-1">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest whitespace-nowrap">
                        Görsel Stil
                    </label>
                    <select
                        className="w-full bg-gray-800 border border-gray-700 rounded p-1.5 text-xs focus:ring-1 focus:ring-yellow-500 outline-none"
                        value={config.style}
                        onChange={(e) => setConfig(prev => ({ ...prev, style: e.target.value }))}
                    >
                        <option value="Classic Comic Book">Klasik Çizgi Roman</option>
                        <option value="Manga">Manga / Anime</option>
                        <option value="Noir">Noir / Siyah Beyaz</option>
                        <option value="Cyberpunk">Cyberpunk</option>
                        <option value="Watercolor">Sulu Boya</option>
                    </select>
                </div>

                {/* Cast Section */}
                <div className="mb-4">
                    <div className="flex justify-between items-center mb-1">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest whitespace-nowrap">
                            Karakterler
                        </label>
                        <span className="text-[10px] text-gray-500 font-mono">{config.cast.length}/4</span>
                    </div>

                    <div className="bg-gray-800/50 rounded-lg p-2 space-y-2 mb-3 border border-gray-700">
                        <div className="space-y-1.5">
                            <input
                                type="text"
                                placeholder="İsim"
                                className="w-full bg-gray-900 border border-gray-600 rounded p-1.5 text-[11px] focus:border-yellow-500 outline-none"
                                value={newCharName}
                                onChange={(e) => setNewCharName(e.target.value)}
                            />
                            <input
                                type="text"
                                placeholder="Görünüm"
                                className="w-full bg-gray-900 border border-gray-600 rounded p-1.5 text-[11px] focus:border-yellow-500 outline-none"
                                value={newCharDesc}
                                onChange={(e) => setNewCharDesc(e.target.value)}
                            />
                            <button
                                onClick={handleAddCharacter}
                                disabled={!newCharName.trim() || isGeneratingAvatar || config.cast.length >= 4}
                                className="w-full bg-gray-700 hover:bg-gray-600 text-white text-[10px] py-1.5 rounded flex items-center justify-center gap-1 transition-colors disabled:opacity-50"
                            >
                                {isGeneratingAvatar ? (
                                    <>
                                        <Loader2 size={12} className="animate-spin" /> Oluşturuluyor...
                                    </>
                                ) : (
                                    <>
                                        <Plus size={12} /> Ekle
                                    </>
                                )}
                            </button>
                        </div>
                    </div>

                    <div className="space-y-1.5">
                        {config.cast.map((char) => (
                        <div
                            key={char.id}
                            className="flex items-center justify-between bg-gray-800/30 p-1.5 rounded border border-gray-700 group hover:border-gray-600 transition-colors"
                        >
                            <div className="flex items-center gap-2 overflow-hidden">
                                <div 
                                    className="w-8 h-8 rounded bg-gray-700 overflow-hidden flex-shrink-0 border border-gray-600 cursor-pointer hover:border-yellow-400 transition-colors"
                                    onClick={() => char.avatarUrl && setPreviewImage(char.avatarUrl)}
                                >
                                    {char.avatarUrl ? (
                                        <img src={char.avatarUrl} alt={char.name} className="w-full h-full object-cover" />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center">
                                            <User size={12} className="text-gray-400" />
                                        </div>
                                    )}
                                </div>
                                <div className="min-w-0">
                                    <p className="text-[11px] font-bold text-gray-200 truncate">{char.name}</p>
                                    <p className="text-[9px] text-gray-500 truncate leading-none">{char.description}</p>
                                </div>
                            </div>
                            <button
                                onClick={() => handleRemoveCharacter(char.id)}
                                className="text-gray-500 hover:text-red-400 transition-colors p-1"
                            >
                                <Trash2 size={12} />
                            </button>
                        </div>
                        ))}
                        {config.cast.length === 0 && (
                        <p className="text-[10px] text-gray-500 text-center py-2 italic">
                            Karakter eklenmedi.
                        </p>
                        )}
                    </div>
                </div>
            </div>

            {/* Sticky Bottom Footer */}
            <div className="p-4 mt-auto border-t border-gray-800 bg-gray-900 flex-shrink-0">
                <button
                    onClick={onGenerate}
                    disabled={isLoading || !config.topic || !config.intro}
                    className={`w-full py-3 rounded-lg font-bold text-sm flex items-center justify-center gap-2 shadow-lg transition-all
                    ${
                        isLoading
                        ? "bg-gray-700 text-gray-400 cursor-not-allowed"
                        : "bg-yellow-500 hover:bg-yellow-400 text-gray-900 hover:scale-[1.02]"
                    }
                    `}
                >
                    {isLoading ? (
                    <>
                        <Loader2 size={16} className="animate-spin" />
                        {status === GeneratorStatus.GENERATING_STORY ? "Yazılıyor..." : "Çiziliyor..."}
                    </>
                    ) : (
                    <>
                        <Play size={16} className="fill-current" />
                        Hikayeyi Çiz
                    </>
                    )}
                </button>
            </div>
        </div>
      </aside>

      {/* Character Image Modal */}
      {previewImage && (
        <div 
          className="fixed inset-0 z-[60] flex items-center justify-center bg-black/90 p-4 backdrop-blur-sm animate-in fade-in duration-200"
          onClick={() => setPreviewImage(null)}
        >
          <div className="relative max-w-sm w-full">
            <button 
                onClick={() => setPreviewImage(null)}
                className="absolute -top-10 right-0 text-white hover:text-yellow-400 transition-colors"
            >
                <X size={28} />
            </button>
            <img 
                src={previewImage} 
                alt="Character Preview" 
                className="w-full h-auto rounded-lg border-2 border-gray-700 shadow-2xl"
                onClick={(e) => e.stopPropagation()} 
            />
          </div>
        </div>
      )}
    </>
  );
};

import React, { useState } from "react";
import { Plus, Trash2, BookOpen, User, Play, Loader2, Sparkles, X, ChevronLeft, Dices } from "lucide-react";
import { Character, ComicConfig, GeneratorStatus } from "../types";
import { generateCharacterAvatar } from "../services/geminiService";

interface SidebarProps {
  config: ComicConfig;
  setConfig: React.Dispatch<React.SetStateAction<ComicConfig>>;
  onGenerate: () => void;
  onAutoFill: () => void;
  status: GeneratorStatus;
  isOpen: boolean;
  onToggle: () => void;
  isAutoFilling?: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({
  config,
  setConfig,
  onGenerate,
  onAutoFill,
  status,
  isOpen,
  onToggle,
  isAutoFilling = false
}) => {
  const [newCharName, setNewCharName] = useState("");
  const [newCharDesc, setNewCharDesc] = useState("");
  const [isGeneratingAvatar, setIsGeneratingAvatar] = useState(false);
  const [previewImage, setPreviewImage] = useState<string | null>(null);

  const handleAddCharacter = async () => {
    if (!newCharName.trim()) return;

    setIsGeneratingAvatar(true);

    try {
        const avatarUrl = await generateCharacterAvatar(newCharName, newCharDesc, config.style);

        const newChar: Character = {
            id: crypto.randomUUID(),
            name: newCharName,
            description: newCharDesc || "Generic appearance",
            avatarUrl: avatarUrl
        };

        setConfig((prev) => ({ ...prev, cast: [...prev.cast, newChar] }));
        setNewCharName("");
        setNewCharDesc("");
    } catch (e) {
        console.error("Avatar error", e);
        const newChar: Character = {
            id: crypto.randomUUID(),
            name: newCharName,
            description: newCharDesc || "Generic appearance",
        };
        setConfig((prev) => ({ ...prev, cast: [...prev.cast, newChar] }));
    } finally {
        setIsGeneratingAvatar(false);
    }
  };

  const handleRemoveCharacter = (id: string) => {
    setConfig((prev) => ({
      ...prev,
      cast: prev.cast.filter((c) => c.id !== id),
    }));
  };

  const isLoading = status !== GeneratorStatus.IDLE && status !== GeneratorStatus.COMPLETE && status !== GeneratorStatus.ERROR;

  return (
    <>
      <aside 
        className={`
            fixed inset-y-0 left-0 z-40 h-full bg-gray-900 text-gray-100 flex flex-col border-r border-gray-800 shadow-2xl transition-all duration-300 ease-in-out
            ${isOpen ? "translate-x-0 w-[280px]" : "-translate-x-full w-0"} 
            md:relative md:translate-x-0 
            ${isOpen ? "md:w-[280px]" : "md:w-0 md:overflow-hidden md:border-none"}
        `}
      >
        <div className="flex flex-col h-full w-full overflow-hidden"> 
            {/* Header - Fixed */}
            <div className="p-4 flex items-center justify-between flex-shrink-0 bg-gray-900 border-b border-gray-800/50">
                <h1 className="text-xl font-bold bg-gradient-to-r from-yellow-400 to-orange-500 bg-clip-text text-transparent flex items-center gap-2 whitespace-nowrap">
                    <BookOpen className="text-yellow-400" size={20} />
                    ComicGen
                </h1>
                <button 
                    onClick={onToggle}
                    className="p-1 hover:bg-gray-800 rounded-full text-gray-400 hover:text-white transition-colors"
                >
                    <ChevronLeft size={18} />
                </button>
            </div>

            {/* Scrollable Area */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-4">

                {/* Auto Fill Button */}
                <button
                    onClick={onAutoFill}
                    disabled={isAutoFilling || isLoading}
                    className="w-full py-2.5 px-3 bg-gradient-to-r from-purple-600 to-blue-600 hover:from-purple-500 hover:to-blue-500 rounded-lg text-xs font-bold flex items-center justify-center gap-2 transition-all shadow-md active:scale-95 disabled:opacity-50"
                >
                    {isAutoFilling ? (
                         <Loader2 size={14} className="animate-spin" />
                    ) : (
                         <Dices size={14} />
                    )}
                    Rastgele Doldur
                </button>

                {/* Topic Section */}
                <div className="space-y-1">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest block">
                        Konu
                    </label>
                    <textarea
                        className="w-full bg-gray-800 border border-gray-700 rounded-lg p-2 text-xs focus:ring-1 focus:ring-yellow-500 outline-none resize-none h-14"
                        placeholder="Örn: Uzayda geçen bir kovboy hikayesi..."
                        value={config.topic}
                        onChange={(e) =>
                            setConfig((prev) => ({ ...prev, topic: e.target.value }))
                        }
                    />
                </div>

                {/* Intro Section */}
                <div className="space-y-1">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest block">
                        Giriş Hikayesi
                    </label>
                    <textarea
                        className="w-full bg-gray-800 border border-gray-700 rounded-lg p-2 text-xs focus:ring-1 focus:ring-yellow-500 outline-none resize-none h-20"
                        placeholder="Hikaye nasıl başlıyor?..."
                        value={config.intro}
                        onChange={(e) =>
                            setConfig((prev) => ({ ...prev, intro: e.target.value }))
                        }
                    />
                </div>

                {/* Style Section */}
                <div className="space-y-1">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest block">
                        Stil
                    </label>
                    <select
                        className="w-full bg-gray-800 border border-gray-700 rounded-lg p-2 text-xs focus:ring-1 focus:ring-yellow-500 outline-none"
                        value={config.style}
                        onChange={(e) => setConfig(prev => ({ ...prev, style: e.target.value }))}
                    >
                        <option value="Classic Comic Book">Klasik Çizgi Roman</option>
                        <option value="Manga">Manga / Anime</option>
                        <option value="Noir">Noir / Siyah Beyaz</option>
                        <option value="Cyberpunk">Cyberpunk</option>
                        <option value="Watercolor">Sulu Boya</option>
                    </select>
                </div>

                {/* Cast Section */}
                <div className="pt-2 border-t border-gray-800/50">
                    <div className="flex justify-between items-center mb-2">
                        <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                            Karakterler ({config.cast.length}/4)
                        </label>
                    </div>

                    <div className="bg-gray-800/40 rounded-xl p-3 space-y-2 border border-gray-700/50 mb-3">
                        <input
                            type="text"
                            placeholder="İsim"
                            className="w-full bg-gray-900/50 border border-gray-700 rounded-md p-2 text-[11px] focus:border-yellow-500 outline-none"
                            value={newCharName}
                            onChange={(e) => setNewCharName(e.target.value)}
                        />
                        <input
                            type="text"
                            placeholder="Görünüm"
                            className="w-full bg-gray-900/50 border border-gray-700 rounded-md p-2 text-[11px] focus:border-yellow-500 outline-none"
                            value={newCharDesc}
                            onChange={(e) => setNewCharDesc(e.target.value)}
                        />
                        <button
                            onClick={handleAddCharacter}
                            disabled={!newCharName.trim() || isGeneratingAvatar || config.cast.length >= 4}
                            className="w-full bg-gray-700 hover:bg-gray-600 text-white text-[10px] py-2 rounded-md flex items-center justify-center gap-1 transition-colors disabled:opacity-50"
                        >
                            {isGeneratingAvatar ? (
                                <Loader2 size={12} className="animate-spin" />
                            ) : (
                                <><Plus size={12} /> Ekle</>
                            )}
                        </button>
                    </div>

                    <div className="space-y-2">
                        {config.cast.map((char) => (
                        <div
                            key={char.id}
                            className="flex items-center justify-between bg-gray-800/30 p-2 rounded-lg border border-gray-800 group transition-all hover:bg-gray-800/50"
                        >
                            <div className="flex items-center gap-3 overflow-hidden">
                                <div 
                                    className="w-10 h-10 rounded-md bg-gray-700 overflow-hidden flex-shrink-0 border border-gray-600 cursor-pointer hover:ring-2 hover:ring-yellow-500 transition-all"
                                    onClick={() => char.avatarUrl && setPreviewImage(char.avatarUrl)}
                                >
                                    {char.avatarUrl ? (
                                        <img src={char.avatarUrl} alt={char.name} className="w-full h-full object-cover" />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center">
                                            <User size={14} className="text-gray-500" />
                                        </div>
                                    )}
                                </div>
                                <div className="min-w-0">
                                    <p className="text-[11px] font-bold text-gray-200 truncate">{char.name}</p>
                                    <p className="text-[9px] text-gray-500 truncate leading-none mt-0.5">{char.description}</p>
                                </div>
                            </div>
                            <button
                                onClick={() => handleRemoveCharacter(char.id)}
                                className="text-gray-600 hover:text-red-400 transition-colors p-1"
                            >
                                <Trash2 size={14} />
                            </button>
                        </div>
                        ))}
                        {config.cast.length === 0 && (
                        <p className="text-[10px] text-gray-600 text-center py-4 italic bg-gray-800/20 rounded-lg border border-dashed border-gray-800">
                            Karakter eklenmedi.
                        </p>
                        )}
                    </div>
                </div>
            </div>

            {/* Footer - Fixed */}
            <div className="p-4 bg-gray-900 border-t border-gray-800 flex-shrink-0">
                <button
                    onClick={onGenerate}
                    disabled={isLoading || !config.topic || !config.intro}
                    className={`w-full py-3.5 rounded-xl font-bold text-sm flex items-center justify-center gap-2 shadow-xl transition-all active:scale-[0.98]
                    ${
                        isLoading
                        ? "bg-gray-800 text-gray-500 cursor-not-allowed"
                        : "bg-yellow-500 hover:bg-yellow-400 text-gray-900"
                    }
                    `}
                >
                    {isLoading ? (
                    <>
                        <Loader2 size={16} className="animate-spin" />
                        {status === GeneratorStatus.GENERATING_STORY ? "Yazılıyor..." : "Çiziliyor..."}
                    </>
                    ) : (
                    <>
                        <Play size={16} className="fill-current" />
                        Çizgi Romanı Başlat
                    </>
                    )}
                </button>
            </div>
        </div>
      </aside>

      {/* Character Image Modal */}
      {previewImage && (
        <div 
          className="fixed inset-0 z-[60] flex items-center justify-center bg-black/90 p-6 backdrop-blur-md animate-in fade-in duration-200"
          onClick={() => setPreviewImage(null)}
        >
          <div className="relative max-w-sm w-full animate-in zoom-in duration-300">
            <button 
                onClick={() => setPreviewImage(null)}
                className="absolute -top-12 right-0 text-white hover:text-yellow-400 p-2"
            >
                <X size={32} />
            </button>
            <img 
                src={previewImage} 
                alt="Character Preview" 
                className="w-full h-auto rounded-2xl border-4 border-gray-800 shadow-[0_0_50px_rgba(0,0,0,0.5)]"
                onClick={(e) => e.stopPropagation()} 
            />
          </div>
        </div>
      )}
    </>
  );
};

import React, { useState } from "react";
import { Plus, Trash2, BookOpen, User, Play, Loader2, Sparkles, X, ChevronLeft, Dices, Zap } from "lucide-react";
import { Character, ComicConfig, GeneratorStatus } from "../types";
import { generateCharacterAvatar } from "../services/geminiService";

interface SidebarProps {
  config: ComicConfig;
  setConfig: React.Dispatch<React.SetStateAction<ComicConfig>>;
  onGenerate: () => void;
  onAutoFill: () => void;
  status: GeneratorStatus;
  isOpen: boolean;
  onToggle: () => void;
  isAutoFilling?: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({
  config,
  setConfig,
  onGenerate,
  onAutoFill,
  status,
  isOpen,
  onToggle,
  isAutoFilling = false
}) => {
  const [newCharName, setNewCharName] = useState("");
  const [newCharDesc, setNewCharDesc] = useState("");
  const [isGeneratingAvatar, setIsGeneratingAvatar] = useState(false);
  const [previewImage, setPreviewImage] = useState<string | null>(null);

  const handleAddCharacter = async () => {
    if (!newCharName.trim()) return;
    setIsGeneratingAvatar(true);
    try {
        const avatarUrl = await generateCharacterAvatar(newCharName, newCharDesc, config.style);
        const newChar: Character = {
            id: crypto.randomUUID(),
            name: newCharName,
            description: newCharDesc || "Gizemli Görünüm",
            avatarUrl: avatarUrl
        };
        setConfig((prev) => ({ ...prev, cast: [...prev.cast, newChar] }));
        setNewCharName("");
        setNewCharDesc("");
    } catch (e) {
        console.error("Avatar error", e);
        const newChar: Character = {
            id: crypto.randomUUID(),
            name: newCharName,
            description: newCharDesc || "Gizemli Görünüm",
        };
        setConfig((prev) => ({ ...prev, cast: [...prev.cast, newChar] }));
    } finally {
        setIsGeneratingAvatar(false);
    }
  };

  const handleRemoveCharacter = (id: string) => {
    setConfig((prev) => ({
      ...prev,
      cast: prev.cast.filter((c) => c.id !== id),
    }));
  };

  const isLoading = status !== GeneratorStatus.IDLE && status !== GeneratorStatus.COMPLETE && status !== GeneratorStatus.ERROR;

  return (
    <>
      <aside 
        className={`
            fixed inset-y-0 left-0 z-40 h-full bg-[#1e293b] text-white flex flex-col border-r-4 border-black transition-all duration-300 ease-in-out
            ${isOpen ? "translate-x-0 w-[300px]" : "-translate-x-full w-0"} 
            md:relative md:translate-x-0 
            ${isOpen ? "md:w-[300px]" : "md:w-0 md:overflow-hidden md:border-none"}
        `}
      >
        <div className="flex flex-col h-full w-full overflow-hidden"> 
            {/* Header - Fixed */}
            <div className="p-4 flex items-center justify-between flex-shrink-0 bg-yellow-400 border-b-4 border-black">
                <h1 className="text-2xl font-display text-black uppercase tracking-tighter flex items-center gap-2">
                    <Zap className="fill-black" size={24} />
                    ComicGen
                </h1>
                <button 
                    onClick={onToggle}
                    className="p-1.5 bg-black text-white rounded hover:bg-gray-800 transition-colors"
                >
                    <ChevronLeft size={20} />
                </button>
            </div>

            {/* Scrollable Main Area */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-5 space-y-6">

                {/* Auto Fill Button */}
                <button
                    onClick={onAutoFill}
                    disabled={isAutoFilling || isLoading}
                    className="w-full py-3 px-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded border-2 border-black shadow-comic hover:shadow-comic-hover hover:translate-x-[2px] hover:translate-y-[2px] transition-all disabled:opacity-50 font-display uppercase tracking-widest text-sm flex items-center justify-center gap-2"
                >
                    {isAutoFilling ? (
                         <Loader2 size={16} className="animate-spin" />
                    ) : (
                         <Sparkles size={16} />
                    )}
                    Hikaye Yarat
                </button>

                {/* Topic & Intro Panels */}
                <div className="space-y-4">
                    <div className="relative group">
                        <label className="absolute -top-2 left-3 bg-yellow-400 text-black px-2 py-0.5 text-[10px] font-display uppercase border-2 border-black z-10">
                            Konu Başlığı
                        </label>
                        <input
                            type="text"
                            className="w-full bg-slate-800 border-2 border-black rounded p-3 pt-4 text-xs font-comic focus:ring-2 focus:ring-yellow-400 outline-none transition-all"
                            placeholder="Örn: Galaksi Korsanları"
                            value={config.topic}
                            onChange={(e) => setConfig((prev) => ({ ...prev, topic: e.target.value }))}
                        />
