                            className="w-full bg-slate-800 border-2 border-black rounded p-3 pt-4 text-xs font-comic focus:ring-2 focus:ring-yellow-400 outline-none resize-none h-24 transition-all"
                            placeholder="Yıl 3042, derin uzayda bir sinyal duyuldu..."
