                            onChange={(e) => setConfig((prev) => ({ ...prev, intro: e.target.value }))}
                        />
                    </div>

                    <div className="relative">
                        <label className="absolute -top-2 left-3 bg-yellow-400 text-black px-2 py-0.5 text-[10px] font-display uppercase border-2 border-black z-10">
                            Görsel Stil
                        </label>
                        <select
                            className="w-full bg-slate-800 border-2 border-black rounded p-3 pt-4 text-xs font-comic focus:ring-2 focus:ring-yellow-400 outline-none appearance-none transition-all cursor-pointer"
                            value={config.style}
                            onChange={(e) => setConfig(prev => ({ ...prev, style: e.target.value }))}
                        >
                            <option value="Classic Comic Book">Klasik Çizgi Roman</option>
                            <option value="Manga">Manga / Anime</option>
                            <option value="Noir">Kara Film (Noir)</option>
                            <option value="Cyberpunk">Cyberpunk</option>
                            <option value="Watercolor">Sulu Boya</option>
                        </select>
                    </div>
                </div>

                {/* Character Factory */}
                <div className="pt-2">
                    <div className="flex justify-between items-center mb-3">
                        <h3 className="font-display text-lg uppercase text-yellow-400 tracking-wider">Karakterler</h3>
                        <span className="font-mono text-xs text-slate-400 bg-slate-900 px-2 py-0.5 rounded border border-slate-700">{config.cast.length}/4</span>
