                    <div className="bg-slate-800 rounded border-2 border-black p-4 space-y-3 mb-4 shadow-comic">
                        <div className="space-y-2">
                            <input
                                type="text"
                                placeholder="İsim"
                                className="w-full bg-slate-900 border border-slate-700 rounded p-2 text-xs font-comic focus:border-yellow-400 outline-none"
