                                onChange={(e) => setNewCharName(e.target.value)}
                            />
                            <input
                                type="text"
                                placeholder="Görünüm (Örn: Mavi zırh, kılıç)"
                                className="w-full bg-slate-900 border border-slate-700 rounded p-2 text-xs font-comic focus:border-yellow-400 outline-none"
                                value={newCharDesc}
                                onChange={(e) => setNewCharDesc(e.target.value)}
                            />
                            <button
                                onClick={handleAddCharacter}
                                disabled={!newCharName.trim() || isGeneratingAvatar || config.cast.length >= 4}
                                className="w-full bg-yellow-400 hover:bg-yellow-300 text-black font-display uppercase py-2 rounded border-2 border-black shadow-comic-hover hover:translate-x-[1px] hover:translate-y-[1px] transition-all disabled:opacity-50"
                            >
                                {isGeneratingAvatar ? (
                                    <Loader2 size={16} className="animate-spin mx-auto" />
                                ) : (
                                    "Ekle"
                                )}
                            </button>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 gap-3">
                        {config.cast.map((char) => (
                        <div
                            key={char.id}
                            className="flex items-center gap-3 bg-slate-800/50 p-2 rounded border-2 border-transparent hover:border-yellow-400 transition-all group"
                        >
                            <div 
                                className="w-12 h-12 rounded bg-slate-700 overflow-hidden flex-shrink-0 border-2 border-black cursor-pointer shadow-comic-hover"
                                onClick={() => char.avatarUrl && setPreviewImage(char.avatarUrl)}
                            >
                                {char.avatarUrl ? (
                                    <img src={char.avatarUrl} alt={char.name} className="w-full h-full object-cover" />
                                ) : (
                                    <div className="w-full h-full flex items-center justify-center">
                                        <User size={18} className="text-slate-500" />
                                    </div>
                                )}
                            </div>
                            <div className="flex-1 min-w-0">
                                <p className="text-xs font-bold text-white truncate font-display uppercase tracking-tight">{char.name}</p>
                                <p className="text-[10px] text-slate-400 truncate font-comic">{char.description}</p>
                            </div>
                            <button
                                onClick={() => handleRemoveCharacter(char.id)}
                                className="text-slate-500 hover:text-red-500 transition-colors p-1"
                            >
                                <Trash2 size={16} />
                            </button>
                        </div>
                        ))}
                        {config.cast.length === 0 && (
                        <div className="py-6 border-2 border-dashed border-slate-700 rounded flex flex-col items-center justify-center opacity-40">
                            <p className="text-[10px] font-comic">Kadro boş...</p>
                        </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Footer - Fixed Action */}
            <div className="p-4 bg-[#1e293b] border-t-4 border-black flex-shrink-0">
                <button
                    onClick={onGenerate}
                    disabled={isLoading || !config.topic || !config.intro}
                    className={`w-full py-4 rounded-lg font-display text-xl uppercase tracking-tighter flex items-center justify-center gap-3 border-4 border-black shadow-comic-lg transition-all active:translate-x-1 active:translate-y-1 active:shadow-none
                    ${
                        isLoading
                        ? "bg-slate-700 text-slate-500 cursor-not-allowed"
                        : "bg-red-500 hover:bg-red-400 text-white"
                    }
                    `}
                >
                    {isLoading ? (
                    <>
                        <Loader2 size={24} className="animate-spin" />
                        Üretiliyor...
                    </>
                    ) : (
                    <>
                        <Play size={20} className="fill-white" />
                        Çizmeye Başla!
                    </>
                    )}
                </button>
            </div>
        </div>
      </aside>

      {/* Hero Avatar Modal */}
      {previewImage && (
        <div 
          className="fixed inset-0 z-[60] flex items-center justify-center bg-black/95 p-6 backdrop-blur-sm animate-in fade-in duration-300"
          onClick={() => setPreviewImage(null)}
        >
          <div className="relative max-w-sm w-full animate-in zoom-in slide-in-from-bottom-10 duration-500">
            <button 
                onClick={() => setPreviewImage(null)}
                className="absolute -top-14 right-0 text-white hover:text-red-500 p-2 bg-black/50 rounded-full transition-all"
            >
                <X size={32} />
            </button>
            <div className="bg-white p-2 rounded-xl border-8 border-black shadow-comic-lg overflow-hidden">
                <img 
                    src={previewImage} 
                    alt="Character Master" 
                    className="w-full h-auto rounded-lg"
                    onClick={(e) => e.stopPropagation()} 
                />
            </div>
          </div>
        </div>
      )}
    </>
  );
};

import React, { useState, useRef, useEffect } from "react";
import { Sidebar } from "./components/Sidebar";
import { ComicPageDisplay } from "./components/ComicPageDisplay";
import {
  ComicConfig,
  ComicPage,
  GeneratorStatus,
  ComicPanelData,
  Character,
} from "./types";
import { generateComicScript, generateFullPageImage, generateSinglePanelImage, generateRandomComicConfig, generateCharacterAvatar } from "./services/geminiService";
import { PlusCircle, Info, Ghost, X, Send, Menu, Sparkles, Loader2, Zap } from "lucide-react";

export default function App() {
  const [config, setConfig] = useState<ComicConfig>({
    topic: "",
    intro: "",
    cast: [],
    style: "Classic Comic Book"
  });

  const [pages, setPages] = useState<ComicPage[]>([]);
  const [status, setStatus] = useState<GeneratorStatus>(GeneratorStatus.IDLE);
  const [isAutoFilling, setIsAutoFilling] = useState(false);

  const [showNextPageModal, setShowNextPageModal] = useState(false);
  const [userDirection, setUserDirection] = useState("");
  const [previewImage, setPreviewImage] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (pages.length > 0) {
      bottomRef.current?.scrollIntoView({ behavior: "smooth" });
    }
  }, [pages.length, status]);

  useEffect(() => {
    if (window.innerWidth < 768) setIsSidebarOpen(false);
  }, []);

  const handleAutoFill = async () => {
    setIsAutoFilling(true);
    try {
        const randomConfig = await generateRandomComicConfig();
        if (randomConfig.cast && randomConfig.topic && randomConfig.intro && randomConfig.style) {
             const newConfig = {
                 ...config,
                 topic: randomConfig.topic,
                 intro: randomConfig.intro,
                 style: randomConfig.style,
                 cast: randomConfig.cast as Character[]
             };
             setConfig(newConfig);

             const castToProcess = [...(randomConfig.cast as Character[])];
             for (let i = 0; i < castToProcess.length; i++) {
                 const char = castToProcess[i];
                 try {
                     const avatarUrl = await generateCharacterAvatar(char.name, char.description, randomConfig.style || "Classic Comic Book");
                     setConfig(prev => ({
                         ...prev,
                         cast: prev.cast.map(c => c.id === char.id ? { ...c, avatarUrl } : c)
                     }));
                 } catch (e) {
                     console.error(`Failed to generate avatar for ${char.name}`, e);
                 }
             }
        }
    } catch (e) {
        console.error("Auto fill failed", e);
        alert("Hikaye kurgusu oluşturulurken bir hata oluştu.");
    } finally {
        setIsAutoFilling(false);
    }
  };

  const handleStartGeneration = async () => {
     if (window.innerWidth < 768) setIsSidebarOpen(false);
     await performGeneration("");
  };

  const handleNextPageClick = () => {
    setUserDirection("");
    setShowNextPageModal(true);
  };

  const confirmNextPageGeneration = () => {
    setShowNextPageModal(false);
    performGeneration(userDirection);
  };

  const performGeneration = async (direction: string) => {
    if (status !== GeneratorStatus.IDLE && status !== GeneratorStatus.COMPLETE && status !== GeneratorStatus.ERROR) return;

    try {
      setStatus(GeneratorStatus.GENERATING_STORY);
      const newPageId = crypto.randomUUID();
      const skeletonPanels: ComicPanelData[] = Array(4).fill({
        imagePrompt: "",
        dialogue: "",
        isLoading: true,
      });

      const newPage: ComicPage = {
        id: newPageId,
        panels: skeletonPanels,
      };

      setPages((prev) => [...prev, newPage]);

      const history = pages.flatMap(p => p.panels.map(panel => panel.dialogue));
      const scriptPanels = await generateComicScript(config, history, direction);

      setPages((prev) =>
        prev.map((p) =>
          p.id === newPageId
            ? { ...p, panels: scriptPanels.map((sp) => ({ ...sp, isLoading: true })) }
            : p
        )
      );

      setStatus(GeneratorStatus.GENERATING_IMAGES);
      const fullPageImageUrl = await generateFullPageImage(scriptPanels, config.style, config.cast);

      setPages((prev) =>
        prev.map((p) =>
          p.id === newPageId
            ? {
                ...p,
                pageImageUrl: fullPageImageUrl,
                panels: p.panels.map((panel) => ({ ...panel, isLoading: false })),
              }
            : p
        )
      );
      setStatus(GeneratorStatus.COMPLETE);
    } catch (error) {
      console.error("Generation failed", error);
      setStatus(GeneratorStatus.ERROR);
      if (status === GeneratorStatus.GENERATING_STORY) {
         setPages(prev => prev.slice(0, -1));
      }
    }
  };

  const handleRegeneratePanel = async (pageId: string, panelIndex: number) => {
      const page = pages.find(p => p.id === pageId);
      if (!page || page.panels[panelIndex].isLoading) return;

      setPages(prev => prev.map(p => {
          if (p.id !== pageId) return p;
          const newPanels = [...p.panels];
          newPanels[panelIndex] = { ...newPanels[panelIndex], isLoading: true };
          return { ...p, panels: newPanels };
      }));

      try {
          const panel = page.panels[panelIndex];
          const newImageUrl = await generateSinglePanelImage(panel.imagePrompt, config.style, config.cast);
          setPages(prev => prev.map(p => {
            if (p.id !== pageId) return p;
            const newPanels = [...p.panels];
            newPanels[panelIndex] = { ...newPanels[panelIndex], isLoading: false, imageUrl: newImageUrl };
            return { ...p, panels: newPanels };
        }));
      } catch (error) {
          console.error("Panel regeneration failed", error);
          setPages(prev => prev.map(p => {
            if (p.id !== pageId) return p;
            const newPanels = [...p.panels];
            newPanels[panelIndex] = { ...newPanels[panelIndex], isLoading: false };
            return { ...p, panels: newPanels };
        }));
      }
  };

  return (
    <div className="flex flex-col md:flex-row h-screen bg-slate-900 font-sans relative overflow-hidden bg-halftone">
      <Sidebar
        config={config}
        setConfig={setConfig}
        onGenerate={handleStartGeneration}
        onAutoFill={handleAutoFill}
        status={status}
        isOpen={isSidebarOpen}
        onToggle={() => setIsSidebarOpen(!isSidebarOpen)}
        isAutoFilling={isAutoFilling}
      />

      {isSidebarOpen && (
          <div className="fixed inset-0 bg-black/60 z-30 md:hidden backdrop-blur-sm transition-all" onClick={() => setIsSidebarOpen(false)} />
      )}

      {!isSidebarOpen && (
        <button
          onClick={() => setIsSidebarOpen(true)}
          className="fixed top-6 left-6 z-20 p-3 bg-yellow-400 rounded border-4 border-black shadow-comic hover:bg-yellow-300 transition-all active:translate-x-1 active:translate-y-1 active:shadow-none"
        >
          <Menu size={24} className="text-black" />
        </button>
      )}

      <main className="flex-1 h-full overflow-y-auto relative custom-scrollbar">
        <div className="max-w-4xl mx-auto px-6 py-12 relative z-10 min-h-full flex flex-col">
          {!isSidebarOpen && <div className="h-16 md:h-0" />}

          {pages.length === 0 && (
            <div className="flex-1 flex flex-col items-center justify-center text-center animate-in fade-in zoom-in duration-700">
              <div className="relative mb-8">
                  <div className="absolute -top-12 -right-12 animate-bounce">
                    <div className="bg-red-500 text-white font-display text-xl px-4 py-2 border-4 border-black rotate-12 shadow-comic">POW!</div>
                  </div>
                  <Ghost size={120} className="text-slate-700 opacity-20" />
              </div>
              <h2 className="text-5xl font-display text-yellow-400 mb-4 uppercase tracking-widest text-outline">Hikaye Başlamadı!</h2>
              <p className="max-w-md mb-10 font-comic text-slate-400 text-lg leading-relaxed">
                Kendi destanını yazmaya hazır mısın? Soldaki menüden kahramanlarını yarat ve ilk maceranı başlat!
              </p>

              <button
                onClick={handleAutoFill}
                disabled={isAutoFilling}
                className="bg-white border-4 border-black text-black font-display text-2xl px-12 py-5 rounded-xl shadow-comic-lg hover:-translate-x-1 hover:-translate-y-1 hover:shadow-[12px_12px_0px_0px_rgba(0,0,0,1)] transition-all flex items-center gap-4 disabled:opacity-50"
              >
                  {isAutoFilling ? <Loader2 className="animate-spin" size={28} /> : <Zap className="fill-yellow-400" size={28} />}
                  HAZIR BİR HİKAYE GETİR
              </button>
            </div>
          )}

          <div className="space-y-16 pb-40">
            {pages.map((page, index) => (
              <ComicPageDisplay 
                key={page.id} 
                page={page} 
                pageIndex={index} 
                onPanelClick={(url) => setPreviewImage(url)}
                onRegeneratePanel={(panelIndex) => handleRegeneratePanel(page.id, panelIndex)}
              />
            ))}
            <div ref={bottomRef} />
          </div>
        </div>

        {pages.length > 0 && status === GeneratorStatus.COMPLETE && (
            <div className="fixed bottom-10 right-10 z-20">
                <button 
                    onClick={handleNextPageClick}
                    className="bg-red-500 hover:bg-red-400 text-white border-4 border-black font-display text-2xl py-4 px-10 rounded-xl shadow-comic-lg hover:-translate-x-1 hover:-translate-y-1 transition-all active:translate-x-1 active:translate-y-1 active:shadow-none flex items-center gap-3"
                >
                    <PlusCircle size={24} />
                    SAYFAYI ÇEVİR
                </button>
            </div>
        )}

        {showNextPageModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/85 backdrop-blur-md p-6">
            <div className="bg-white rounded-2xl shadow-[0_0_100px_rgba(251,191,36,0.2)] w-full max-w-xl overflow-hidden border-8 border-black animate-in fade-in zoom-in duration-300">
               <div className="bg-yellow-400 p-5 border-b-8 border-black flex justify-between items-center">
                  <h3 className="font-display text-3xl uppercase tracking-wider text-black">BÖLÜMÜ KURGULA</h3>
                  <button onClick={() => setShowNextPageModal(false)} className="text-black hover:text-red-600 transition-colors">
                    <X size={32} />
                  </button>
               </div>
               <div className="p-8">
                 <p className="text-sm font-bold text-slate-500 mb-4 font-comic uppercase tracking-tighter">Sıradaki karelerde neler yaşanacak?</p>
                 <textarea 
                    className="w-full h-40 bg-slate-50 border-4 border-black rounded-xl p-6 text-black focus:ring-4 focus:ring-yellow-200 outline-none resize-none font-comic text-xl placeholder:opacity-30"
