                    autoFocus
                 />
               </div>
               <div className="bg-slate-50 p-6 border-t-4 border-slate-100 flex justify-end gap-6">
                  <button onClick={() => setShowNextPageModal(false)} className="px-6 py-2 font-display text-slate-400 hover:text-black uppercase transition-colors">Vazgeç</button>
                  <button 
                    onClick={confirmNextPageGeneration}
