import { GoogleGenAI, Type, Schema } from "@google/genai";
import { ComicConfig, ComicPanelData, Character } from "../types";

// Initialize the client
// The API key is injected automatically via process.env.API_KEY
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const STORY_MODEL = "gemini-3-flash-preview";
const IMAGE_MODEL = "gemini-2.5-flash-image";

/**
 * Helper to retry operations on 429 errors
 */
async function retryOperation<T>(operation: () => Promise<T>, retries = 3, delay = 2000): Promise<T> {
  try {
    return await operation();
  } catch (error: any) {
    const isQuotaError = error?.status === 429 || 
                         error?.code === 429 || 
                         error?.message?.includes('429') ||
                         error?.message?.includes('quota') ||
                         error?.toString().includes('429');

    if (isQuotaError && retries > 0) {
      console.warn(`Quota hit. Retrying in ${delay}ms... (${retries} attempts left)`);
      await new Promise(resolve => setTimeout(resolve, delay));
      return retryOperation(operation, retries - 1, delay * 2);
    }
    throw error;
  }
}

/**
 * Generates an avatar image for a character using a specific Character Sheet template.
 */
export const generateCharacterAvatar = async (
  name: string,
  description: string,
  style: string
): Promise<string> => {
  try {
    const prompt = `
      Character Design Reference Sheet for ${name}.
      Layout: Structured Character Template.

      Visual Elements Required:
      1. LEFT SIDE: A detailed Full Body shot showing the character's outfit, physique, and stance.
      2. RIGHT SIDE (Top): A Close-up Portrait (Headshot) focusing on facial features and expression.
      3. RIGHT SIDE (Bottom): A stylized text block listing 'Name' and 'Attributes' (as aesthetic visual elements).

      Character Details: ${description}.
      Art Style: ${style}.
      Background: Clean, neutral or white studio background. Professional concept art style.
    `;

    const response = await retryOperation(() => ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: prompt,
    }));

    let base64Image = "";
    const parts = response.candidates?.[0]?.content?.parts;

    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          base64Image = part.inlineData.data;
          break;
        }
      }
    }

    if (!base64Image) return "";
    return `data:image/png;base64,${base64Image}`;
  } catch (error) {
    console.error("Avatar generation error:", error);
    return "";
  }
};

/**
 * Generates a random comic configuration (Topic, Intro, Cast).
 */
export const generateRandomComicConfig = async (): Promise<Partial<ComicConfig>> => {
    const prompt = `
      Generate a creative, unique, and exciting comic book concept in Turkish.

      Output JSON format:
      {
        "topic": "A short, catchy title/topic",
        "intro": "An engaging opening paragraph setting the scene (2-3 sentences)",
        "style": "One of: 'Classic Comic Book', 'Manga', 'Noir', 'Cyberpunk', 'Watercolor'",
        "cast": [
          { "name": "Character Name", "description": "Visual description (clothing, hair, distinct features)" },
          { "name": "Character Name", "description": "Visual description" }
        ]
      }

      Generate 2 or 3 distinct characters.
    `;

    const responseSchema: Schema = {
      type: Type.OBJECT,
      properties: {
        topic: { type: Type.STRING },
        intro: { type: Type.STRING },
        style: { type: Type.STRING },
        cast: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING },
            },
            required: ["name", "description"]
          }
        }
      },
      required: ["topic", "intro", "style", "cast"]
    };

    try {
      const response = await retryOperation(() => ai.models.generateContent({
        model: STORY_MODEL,
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: responseSchema,
        },
      }));

      const text = response.text;
      if (!text) throw new Error("No config generated");

      const data = JSON.parse(text);

      // Add IDs to characters
      const castWithIds = data.cast.map((c: any) => ({
          ...c,
          id: crypto.randomUUID(),
      }));

      return {
          ...data,
          cast: castWithIds
      };
    } catch (error) {
      console.error("Random config generation error:", error);
      throw error;
    }
  };

/**
 * Generates the script/storyboard for the next 4 panels based on inputs.
 */
export const generateComicScript = async (
  config: ComicConfig,
  history: string[],
  userDirection: string = ""
): Promise<ComicPanelData[]> => {
  const castDescription = config.cast
    .map((c) => `${c.name} (${c.description})`)
    .join(", ");

  const previousContext = history.length > 0 ? history.join("\n") : "None yet.";

  const directionPrompt = userDirection 
    ? `IMPORTANT USER DIRECTION FOR THIS PAGE: ${userDirection}` 
    : "Continue the story logically from previous events.";

  const prompt = `
    You are a professional comic book writer.
    Topic: ${config.topic}
    Cast: ${castDescription}
    Story Start/Context: ${config.intro}
    Previous Events: ${previousContext}

    ${directionPrompt}

    Task: Write the script for the NEXT 4 panels of this comic.

    For each panel, provide:
    1. 'imagePrompt': A highly detailed visual description of the scene. Include character appearance, action, setting, and lighting. Describe it as a comic book panel style. ALWAYS include the character names clearly in the prompt if they appear.
    2. 'dialogue': The text spoken by characters or a narrator caption. Keep it brief.
  `;

  const responseSchema: Schema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        imagePrompt: {
          type: Type.STRING,
          description: "Visual description for image generation",
        },
        dialogue: {
          type: Type.STRING,
          description: "Dialogue or caption text",
        },
      },
      required: ["imagePrompt", "dialogue"],
    },
  };

  try {
    const response = await retryOperation(() => ai.models.generateContent({
      model: STORY_MODEL,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        systemInstruction: "You are a comic book creator. Generate exciting and consistent storyboards.",
      },
    }));

    const text = response.text;
    if (!text) throw new Error("No script generated");

    return JSON.parse(text) as ComicPanelData[];
  } catch (error) {
    console.error("Script generation error:", error);
    throw error;
  }
};

/**
 * Generates a SINGLE full-page image containing a 2x2 grid of panels.
 * This saves quota by making 1 API call instead of 4.
 */
export const generateFullPageImage = async (
  panels: ComicPanelData[],
  style: string,
  cast: Character[]
): Promise<string> => {
  try {
    const parts: any[] = [];

    // 1. Construct a master prompt that describes the 2x2 layout
    let layoutDescription = `
      Create a full Comic Book Page with a STRICT 2x2 GRID LAYOUT (4 panels total).
      Art Style: ${style}.
      Quality: High definition, vibrant colors, clean thick panel borders (gutters).

      STRICT PLACEMENT RULES:
      1. ONLY draw characters if they are explicitly named in the description for that specific panel.
      2. If a panel description describes a landscape or object, DO NOT insert characters.
      3. Do not bleed characters from one panel to another.

      Content:
    `;

    panels.forEach((p, i) => {
        const position = i === 0 ? "Top-Left" : i === 1 ? "Top-Right" : i === 2 ? "Bottom-Left" : "Bottom-Right";
        layoutDescription += `\nPANEL ${i+1} (${position}): ${p.imagePrompt}`;
    });

    // 2. Identify all characters present in the entire page for reference
    const uniqueCharactersInPage = new Set<string>();
    panels.forEach(p => {
        cast.forEach(c => {
            if (p.imagePrompt.toLowerCase().includes(c.name.toLowerCase())) {
                uniqueCharactersInPage.add(c.id);
            }
        });
    });

    // 3. Add reference images for consistent characters
    const matchedCharacters = cast.filter(c => uniqueCharactersInPage.has(c.id) && c.avatarUrl);

    let referenceInstructions = "";
    if (matchedCharacters.length > 0) {
        referenceInstructions = "\n\nREFERENCE LIBRARY: I have provided reference images for the following characters: " + matchedCharacters.map(c => c.name).join(", ") + ". USE THESE REFERENCES TO DRAW THE CHARACTERS CORRECTLY, BUT ONLY DRAW THEM IN THE PANELS WHERE THEIR NAME APPEARS IN THE TEXT.";

        for (const char of matchedCharacters) {
            if (char.avatarUrl) {
                // Remove the data URL prefix to get raw base64
                const base64Data = char.avatarUrl.split(',')[1];
                parts.push({
                    inlineData: {
                        data: base64Data,
                        mimeType: "image/png"
                    }
                });
            }
        }
    }

    const finalPrompt = `${layoutDescription} ${referenceInstructions}`;

    // Add text prompt as the last part
    parts.push({ text: finalPrompt });

    const response = await retryOperation(() => ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: { parts: parts },
      config: {
          aspectRatio: "1:1", // Square page for 2x2 grid
          imageSize: "1K" // Standard resolution is fine
      }
    }));

    // Extract image
    let base64Image = "";
    const resParts = response.candidates?.[0]?.content?.parts;

    if (resParts) {
      for (const part of resParts) {
        if (part.inlineData && part.inlineData.data) {
          base64Image = part.inlineData.data;
          break;
        }
      }
    }

    if (!base64Image) {
        console.warn("No image data found in response.");
        return ""; 
    }

    return `data:image/png;base64,${base64Image}`;
  } catch (error) {
    console.error("Image generation error:", error);
    return ""; 
  }
};

/**
 * Generates a SINGLE image for a specific panel.
 * Used for regenerating a specific panel if the user is not satisfied.
 */
export const generateSinglePanelImage = async (
  panelPrompt: string,
  style: string,
  cast: Character[]
): Promise<string> => {
  try {
    const parts: any[] = [];

    // Check for characters in this specific panel
    const matchedCharacters = cast.filter(c => 
        panelPrompt.toLowerCase().includes(c.name.toLowerCase()) && c.avatarUrl
    );

    let referenceInstructions = "";
    if (matchedCharacters.length > 0) {
        referenceInstructions = " IMPORTANT: Maintain exact character consistency (face, hair, clothing) for: " + matchedCharacters.map(c => c.name).join(", ") + " using the attached references.";

        for (const char of matchedCharacters) {
             const base64Data = char.avatarUrl!.split(',')[1];
             parts.push({
                inlineData: {
                    data: base64Data,
                    mimeType: "image/png"
                }
             });
        }
    }

    const finalPrompt = `Comic book panel, ${style} style. ${panelPrompt}.${referenceInstructions} High quality, vibrant colors, clear outlines, dynamic composition.`;

    parts.push({ text: finalPrompt });

    const response = await retryOperation(() => ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: { parts: parts },
      config: {
        aspectRatio: "1:1",
        imageSize: "1K"
      }
    }));

    let base64Image = "";
    const resParts = response.candidates?.[0]?.content?.parts;

    if (resParts) {
      for (const part of resParts) {
        if (part.inlineData && part.inlineData.data) {
          base64Image = part.inlineData.data;
          break;
        }
      }
    }

    if (!base64Image) return "";
    return `data:image/png;base64,${base64Image}`;
  } catch (error) {
    console.error("Single panel generation error:", error);
    return "";
  }
};

import React, { useState, useRef, useEffect } from "react";
import { Sidebar } from "./components/Sidebar";
import { ComicPageDisplay } from "./components/ComicPageDisplay";
import {
  ComicConfig,
  ComicPage,
  GeneratorStatus,
  ComicPanelData,
  Character,
} from "./types";
import { generateComicScript, generateFullPageImage, generateSinglePanelImage, generateRandomComicConfig, generateCharacterAvatar } from "./services/geminiService";
import { PlusCircle, Info, Ghost, X, Send, Menu, Sparkles, Loader2, Zap } from "lucide-react";

export default function App() {
  const [config, setConfig] = useState<ComicConfig>({
    topic: "",
    intro: "",
    cast: [],
    style: "Classic Comic Book"
  });

  const [pages, setPages] = useState<ComicPage[]>([]);
  const [status, setStatus] = useState<GeneratorStatus>(GeneratorStatus.IDLE);
  const [isAutoFilling, setIsAutoFilling] = useState(false);

  const [showNextPageModal, setShowNextPageModal] = useState(false);
  const [userDirection, setUserDirection] = useState("");
  const [previewImage, setPreviewImage] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (pages.length > 0) {
      bottomRef.current?.scrollIntoView({ behavior: "smooth" });
    }
  }, [pages.length, status]);

  useEffect(() => {
    if (window.innerWidth < 768) setIsSidebarOpen(false);
  }, []);

  const handleAutoFill = async () => {
    setIsAutoFilling(true);
    try {
        const randomConfig = await generateRandomComicConfig();
        if (randomConfig.cast && randomConfig.topic && randomConfig.intro && randomConfig.style) {
             const newConfig = {
                 ...config,
                 topic: randomConfig.topic,
                 intro: randomConfig.intro,
                 style: randomConfig.style,
                 cast: randomConfig.cast as Character[]
             };
             setConfig(newConfig);

             const castToProcess = [...(randomConfig.cast as Character[])];
             for (let i = 0; i < castToProcess.length; i++) {
                 const char = castToProcess[i];
                 try {
                     // Add delay to prevent rate limiting
                     if (i > 0) await new Promise(resolve => setTimeout(resolve, 2000));

                     const avatarUrl = await generateCharacterAvatar(char.name, char.description, randomConfig.style || "Classic Comic Book");
                     setConfig(prev => ({
                         ...prev,
                         cast: prev.cast.map(c => c.id === char.id ? { ...c, avatarUrl } : c)
                     }));
                 } catch (e) {
                     console.error(`Failed to generate avatar for ${char.name}`, e);
                 }
             }
        }
    } catch (e) {
        console.error("Auto fill failed", e);
        alert("Hikaye kurgusu oluşturulurken bir hata oluştu.");
    } finally {
        setIsAutoFilling(false);
    }
  };

  const handleStartGeneration = async () => {
     if (window.innerWidth < 768) setIsSidebarOpen(false);
     await performGeneration("");
  };

  const handleNextPageClick = () => {
    setUserDirection("");
    setShowNextPageModal(true);
  };

  const confirmNextPageGeneration = () => {
    setShowNextPageModal(false);
    performGeneration(userDirection);
  };

  const performGeneration = async (direction: string) => {
    if (status !== GeneratorStatus.IDLE && status !== GeneratorStatus.COMPLETE && status !== GeneratorStatus.ERROR) return;

    try {
      setStatus(GeneratorStatus.GENERATING_STORY);
      const newPageId = crypto.randomUUID();
      const skeletonPanels: ComicPanelData[] = Array(4).fill({
        imagePrompt: "",
        dialogue: "",
        isLoading: true,
      });

      const newPage: ComicPage = {
        id: newPageId,
        panels: skeletonPanels,
      };

      setPages((prev) => [...prev, newPage]);

      const history = pages.flatMap(p => p.panels.map(panel => panel.dialogue));
      const scriptPanels = await generateComicScript(config, history, direction);

      setPages((prev) =>
        prev.map((p) =>
          p.id === newPageId
            ? { ...p, panels: scriptPanels.map((sp) => ({ ...sp, isLoading: true })) }
            : p
        )
      );

      setStatus(GeneratorStatus.GENERATING_IMAGES);
      const fullPageImageUrl = await generateFullPageImage(scriptPanels, config.style, config.cast);

      setPages((prev) =>
        prev.map((p) =>
          p.id === newPageId
            ? {
                ...p,
                pageImageUrl: fullPageImageUrl,
                panels: p.panels.map((panel) => ({ ...panel, isLoading: false })),
              }
            : p
        )
      );
      setStatus(GeneratorStatus.COMPLETE);
    } catch (error) {
      console.error("Generation failed", error);
      setStatus(GeneratorStatus.ERROR);
      if (status === GeneratorStatus.GENERATING_STORY) {
         setPages(prev => prev.slice(0, -1));
      }
    }
  };

  const handleRegeneratePanel = async (pageId: string, panelIndex: number) => {
      const page = pages.find(p => p.id === pageId);
      if (!page || page.panels[panelIndex].isLoading) return;

      setPages(prev => prev.map(p => {
          if (p.id !== pageId) return p;
          const newPanels = [...p.panels];
          newPanels[panelIndex] = { ...newPanels[panelIndex], isLoading: true };
          return { ...p, panels: newPanels };
      }));

      try {
          const panel = page.panels[panelIndex];
          const newImageUrl = await generateSinglePanelImage(panel.imagePrompt, config.style, config.cast);
          setPages(prev => prev.map(p => {
            if (p.id !== pageId) return p;
            const newPanels = [...p.panels];
            newPanels[panelIndex] = { ...newPanels[panelIndex], isLoading: false, imageUrl: newImageUrl };
            return { ...p, panels: newPanels };
        }));
      } catch (error) {
          console.error("Panel regeneration failed", error);
          setPages(prev => prev.map(p => {
            if (p.id !== pageId) return p;
            const newPanels = [...p.panels];
            newPanels[panelIndex] = { ...newPanels[panelIndex], isLoading: false };
            return { ...p, panels: newPanels };
        }));
      }
  };

  return (
    <div className="flex flex-col md:flex-row h-screen bg-slate-900 font-sans relative overflow-hidden bg-halftone">
      <Sidebar
        config={config}
        setConfig={setConfig}
        onGenerate={handleStartGeneration}
        onAutoFill={handleAutoFill}
        status={status}
        isOpen={isSidebarOpen}
        onToggle={() => setIsSidebarOpen(!isSidebarOpen)}
        isAutoFilling={isAutoFilling}
      />

      {isSidebarOpen && (
          <div className="fixed inset-0 bg-black/60 z-30 md:hidden backdrop-blur-sm transition-all" onClick={() => setIsSidebarOpen(false)} />
      )}

      {!isSidebarOpen && (
        <button
          onClick={() => setIsSidebarOpen(true)}
          className="fixed top-6 left-6 z-20 p-3 bg-yellow-400 rounded border-4 border-black shadow-comic hover:bg-yellow-300 transition-all active:translate-x-1 active:translate-y-1 active:shadow-none"
        >
          <Menu size={24} className="text-black" />
        </button>
      )}

      <main className="flex-1 h-full overflow-y-auto relative custom-scrollbar">
        <div className="max-w-4xl mx-auto px-6 py-12 relative z-10 min-h-full flex flex-col">
          {!isSidebarOpen && <div className="h-16 md:h-0" />}

          {pages.length === 0 && (
            <div className="flex-1 flex flex-col items-center justify-center text-center animate-in fade-in zoom-in duration-700">
              <div className="relative mb-8">
                  <div className="absolute -top-12 -right-12 animate-bounce">
                    <div className="bg-red-500 text-white font-display text-xl px-4 py-2 border-4 border-black rotate-12 shadow-comic">POW!</div>
                  </div>
                  <Ghost size={120} className="text-slate-700 opacity-20" />
              </div>
              <h2 className="text-5xl font-display text-yellow-400 mb-4 uppercase tracking-widest text-outline">Hikaye Başlamadı!</h2>
              <p className="max-w-md mb-10 font-comic text-slate-400 text-lg leading-relaxed">
                Kendi destanını yazmaya hazır mısın? Soldaki menüden kahramanlarını yarat ve ilk maceranı başlat!
              </p>

              <button
                onClick={handleAutoFill}
                disabled={isAutoFilling}
                className="bg-white border-4 border-black text-black font-display text-2xl px-12 py-5 rounded-xl shadow-comic-lg hover:-translate-x-1 hover:-translate-y-1 hover:shadow-[12px_12px_0px_0px_rgba(0,0,0,1)] transition-all flex items-center gap-4 disabled:opacity-50"
              >
                  {isAutoFilling ? <Loader2 className="animate-spin" size={28} /> : <Zap className="fill-yellow-400" size={28} />}
                  HAZIR BİR HİKAYE GETİR
              </button>
            </div>
          )}

          <div className="space-y-16 pb-40">
            {pages.map((page, index) => (
              <ComicPageDisplay 
                key={page.id} 
                page={page} 
                pageIndex={index} 
                onPanelClick={(url) => setPreviewImage(url)}
                onRegeneratePanel={(panelIndex) => handleRegeneratePanel(page.id, panelIndex)}
              />
            ))}
            <div ref={bottomRef} />
          </div>
        </div>

        {pages.length > 0 && status === GeneratorStatus.COMPLETE && (
            <div className="fixed bottom-10 right-10 z-20">
                <button 
                    onClick={handleNextPageClick}
                    className="bg-red-500 hover:bg-red-400 text-white border-4 border-black font-display text-2xl py-4 px-10 rounded-xl shadow-comic-lg hover:-translate-x-1 hover:-translate-y-1 transition-all active:translate-x-1 active:translate-y-1 active:shadow-none flex items-center gap-3"
                >
                    <PlusCircle size={24} />
                    SAYFAYI ÇEVİR
                </button>
            </div>
        )}

        {showNextPageModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/85 backdrop-blur-md p-6">
            <div className="bg-white rounded-2xl shadow-[0_0_100px_rgba(251,191,36,0.2)] w-full max-w-xl overflow-hidden border-8 border-black animate-in fade-in zoom-in duration-300">
               <div className="bg-yellow-400 p-5 border-b-8 border-black flex justify-between items-center">
                  <h3 className="font-display text-3xl uppercase tracking-wider text-black">BÖLÜMÜ KURGULA</h3>
                  <button onClick={() => setShowNextPageModal(false)} className="text-black hover:text-red-600 transition-colors">
                    <X size={32} />
                  </button>
               </div>
               <div className="p-8">
                 <p className="text-sm font-bold text-slate-500 mb-4 font-comic uppercase tracking-tighter">Sıradaki karelerde neler yaşanacak?</p>
                 <textarea 
                    className="w-full h-40 bg-slate-50 border-4 border-black rounded-xl p-6 text-black focus:ring-4 focus:ring-yellow-200 outline-none resize-none font-comic text-xl placeholder:opacity-30"
                    placeholder="Örn: Kahramanımız karanlık mağarada eski bir kılıç bulur..."
                    value={userDirection}
                    onChange={(e) => setUserDirection(e.target.value)}
                    autoFocus
                 />
               </div>
               <div className="bg-slate-50 p-6 border-t-4 border-slate-100 flex justify-end gap-6">
                  <button onClick={() => setShowNextPageModal(false)} className="px-6 py-2 font-display text-slate-400 hover:text-black uppercase transition-colors">Vazgeç</button>
                  <button 
                    onClick={confirmNextPageGeneration}
                    className="px-10 py-4 bg-black text-white font-display text-xl rounded-lg hover:bg-slate-800 transition-all shadow-comic"
                  >
                    KARELERİ ÇİZ!
                  </button>
               </div>
            </div>
          </div>
        )}

        {previewImage && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/98 p-4 md:p-12 backdrop-blur-2xl animate-in fade-in duration-400" onClick={() => setPreviewImage(null)}>
            <div className="relative max-w-6xl w-full max-h-[90vh] flex items-center justify-center animate-in zoom-in duration-500">
              <button onClick={() => setPreviewImage(null)} className="absolute -top-16 right-0 text-white hover:text-yellow-400 bg-white/10 p-2 rounded-full transition-all">
                <X size={32} />
              </button>
              <div className="bg-white p-2 rounded-lg border-[12px] border-black shadow-[0_0_100px_rgba(255,255,255,0.1)]">
                <img src={previewImage} alt="Full Detail" className="max-w-full max-h-[75vh] object-contain rounded" onClick={(e) => e.stopPropagation()} />
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

import { GoogleGenAI, Type, Schema, GenerateContentResponse } from "@google/genai";
import { ComicConfig, ComicPanelData, Character } from "../types";

// Initialize the client
// The API key is injected automatically via process.env.API_KEY
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const STORY_MODEL = "gemini-3-flash-preview";
const IMAGE_MODEL = "gemini-2.5-flash-image";

/**
 * Helper to retry operations on 429 errors
 */
async function retryOperation<T>(operation: () => Promise<T>, retries = 3, delay = 2000): Promise<T> {
  try {
    return await operation();
  } catch (error: any) {
    const isQuotaError = error?.status === 429 || 
                         error?.code === 429 || 
                         error?.message?.includes('429') ||
                         error?.message?.includes('quota') ||
                         error?.toString().includes('429');

    if (isQuotaError && retries > 0) {
      console.warn(`Quota hit. Retrying in ${delay}ms... (${retries} attempts left)`);
      await new Promise(resolve => setTimeout(resolve, delay));
      return retryOperation(operation, retries - 1, delay * 2);
    }
    throw error;
  }
}

/**
 * Generates an avatar image for a character using a specific Character Sheet template.
 */
export const generateCharacterAvatar = async (
  name: string,
  description: string,
  style: string
): Promise<string> => {
  try {
    const prompt = `
      Character Design Reference Sheet for ${name}.
      Layout: Structured Character Template.

      Visual Elements Required:
      1. LEFT SIDE: A detailed Full Body shot showing the character's outfit, physique, and stance.
      2. RIGHT SIDE (Top): A Close-up Portrait (Headshot) focusing on facial features and expression.
      3. RIGHT SIDE (Bottom): A stylized text block listing 'Name' and 'Attributes' (as aesthetic visual elements).

      Character Details: ${description}.
      Art Style: ${style}.
      Background: Clean, neutral or white studio background. Professional concept art style.
    `;

    const response = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: prompt,
    }));

    let base64Image = "";
    const parts = response.candidates?.[0]?.content?.parts;

    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          base64Image = part.inlineData.data;
          break;
        }
      }
    }

    if (!base64Image) return "";
    return `data:image/png;base64,${base64Image}`;
  } catch (error) {
    console.error("Avatar generation error:", error);
    return "";
  }
};

/**
 * Generates a random comic configuration (Topic, Intro, Cast).
 */
export const generateRandomComicConfig = async (): Promise<Partial<ComicConfig>> => {
    const prompt = `
      Generate a creative, unique, and exciting comic book concept in Turkish.

      Output JSON format:
      {
        "topic": "A short, catchy title/topic",
        "intro": "An engaging opening paragraph setting the scene (2-3 sentences)",
        "style": "One of: 'Classic Comic Book', 'Manga', 'Noir', 'Cyberpunk', 'Watercolor'",
        "cast": [
          { "name": "Character Name", "description": "Visual description (clothing, hair, distinct features)" },
          { "name": "Character Name", "description": "Visual description" }
        ]
      }

      Generate 2 or 3 distinct characters.
    `;

    const responseSchema: Schema = {
      type: Type.OBJECT,
      properties: {
        topic: { type: Type.STRING },
        intro: { type: Type.STRING },
        style: { type: Type.STRING },
        cast: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING },
            },
            required: ["name", "description"]
          }
        }
      },
      required: ["topic", "intro", "style", "cast"]
    };

    try {
      const response = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
        model: STORY_MODEL,
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: responseSchema,
        },
      }));

      const text = response.text;
      if (!text) throw new Error("No config generated");

      const data = JSON.parse(text);

      // Add IDs to characters
      const castWithIds = data.cast.map((c: any) => ({
          ...c,
          id: crypto.randomUUID(),
      }));

      return {
          ...data,
          cast: castWithIds
      };
    } catch (error) {
      console.error("Random config generation error:", error);
      throw error;
    }
  };

/**
 * Generates the script/storyboard for the next 4 panels based on inputs.
 */
export const generateComicScript = async (
  config: ComicConfig,
  history: string[],
  userDirection: string = ""
): Promise<ComicPanelData[]> => {
  const castDescription = config.cast
    .map((c) => `${c.name} (${c.description})`)
    .join(", ");

  const previousContext = history.length > 0 ? history.join("\n") : "None yet.";

  const directionPrompt = userDirection 
    ? `IMPORTANT USER DIRECTION FOR THIS PAGE: ${userDirection}` 
    : "Continue the story logically from previous events.";

  const prompt = `
    You are a professional comic book writer.
    Topic: ${config.topic}
    Cast: ${castDescription}
    Story Start/Context: ${config.intro}
    Previous Events: ${previousContext}

    ${directionPrompt}

    Task: Write the script for the NEXT 4 panels of this comic.

    For each panel, provide:
    1. 'imagePrompt': A highly detailed visual description of the scene. Include character appearance, action, setting, and lighting. Describe it as a comic book panel style. ALWAYS include the character names clearly in the prompt if they appear.
    2. 'dialogue': The text spoken by characters or a narrator caption. Keep it brief.
  `;

  const responseSchema: Schema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        imagePrompt: {
          type: Type.STRING,
          description: "Visual description for image generation",
        },
        dialogue: {
          type: Type.STRING,
          description: "Dialogue or caption text",
        },
      },
      required: ["imagePrompt", "dialogue"],
    },
  };

  try {
    const response = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
      model: STORY_MODEL,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        systemInstruction: "You are a comic book creator. Generate exciting and consistent storyboards.",
      },
    }));

    const text = response.text;
    if (!text) throw new Error("No script generated");

    return JSON.parse(text) as ComicPanelData[];
  } catch (error) {
    console.error("Script generation error:", error);
    throw error;
  }
};

/**
 * Generates a SINGLE full-page image containing a 2x2 grid of panels.
 * This saves quota by making 1 API call instead of 4.
 */
export const generateFullPageImage = async (
  panels: ComicPanelData[],
  style: string,
  cast: Character[]
): Promise<string> => {
  try {
    const parts: any[] = [];

    // 1. Construct a master prompt that describes the 2x2 layout
    let layoutDescription = `
      Create a full Comic Book Page with a STRICT 2x2 GRID LAYOUT (4 panels total).
      Art Style: ${style}.
      Quality: High definition, vibrant colors, clean thick panel borders (gutters).

      STRICT PLACEMENT RULES:
      1. ONLY draw characters if they are explicitly named in the description for that specific panel.
      2. If a panel description describes a landscape or object, DO NOT insert characters.
      3. Do not bleed characters from one panel to another.

      Content:
    `;

    panels.forEach((p, i) => {
        const position = i === 0 ? "Top-Left" : i === 1 ? "Top-Right" : i === 2 ? "Bottom-Left" : "Bottom-Right";
        layoutDescription += `\nPANEL ${i+1} (${position}): ${p.imagePrompt}`;
    });

    // 2. Identify all characters present in the entire page for reference
    const uniqueCharactersInPage = new Set<string>();
    panels.forEach(p => {
        cast.forEach(c => {
            if (p.imagePrompt.toLowerCase().includes(c.name.toLowerCase())) {
                uniqueCharactersInPage.add(c.id);
            }
        });
    });

    // 3. Add reference images for consistent characters
    const matchedCharacters = cast.filter(c => uniqueCharactersInPage.has(c.id) && c.avatarUrl);

    let referenceInstructions = "";
    if (matchedCharacters.length > 0) {
        referenceInstructions = "\n\nREFERENCE LIBRARY: I have provided reference images for the following characters: " + matchedCharacters.map(c => c.name).join(", ") + ". USE THESE REFERENCES TO DRAW THE CHARACTERS CORRECTLY, BUT ONLY DRAW THEM IN THE PANELS WHERE THEIR NAME APPEARS IN THE TEXT.";

        for (const char of matchedCharacters) {
            if (char.avatarUrl) {
                // Remove the data URL prefix to get raw base64
                const base64Data = char.avatarUrl.split(',')[1];
                parts.push({
                    inlineData: {
                        data: base64Data,
                        mimeType: "image/png"
                    }
                });
            }
        }
    }

    const finalPrompt = `${layoutDescription} ${referenceInstructions}`;

    // Add text prompt as the last part
    parts.push({ text: finalPrompt });

    const response = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: { parts: parts },
      config: {
          aspectRatio: "1:1", // Square page for 2x2 grid
          imageSize: "1K" // Standard resolution is fine
      }
    }));

    // Extract image
    let base64Image = "";
    const resParts = response.candidates?.[0]?.content?.parts;

    if (resParts) {
      for (const part of resParts) {
        if (part.inlineData && part.inlineData.data) {
          base64Image = part.inlineData.data;
          break;
        }
      }
    }

    if (!base64Image) {
        console.warn("No image data found in response.");
        return ""; 
    }

    return `data:image/png;base64,${base64Image}`;
  } catch (error) {
    console.error("Image generation error:", error);
    return ""; 
  }
};

/**
 * Generates a SINGLE image for a specific panel.
 * Used for regenerating a specific panel if the user is not satisfied.
 */
export const generateSinglePanelImage = async (
  panelPrompt: string,
  style: string,
  cast: Character[]
): Promise<string> => {
  try {
    const parts: any[] = [];

    // Check for characters in this specific panel
    const matchedCharacters = cast.filter(c => 
        panelPrompt.toLowerCase().includes(c.name.toLowerCase()) && c.avatarUrl
    );

    let referenceInstructions = "";
    if (matchedCharacters.length > 0) {
        referenceInstructions = " IMPORTANT: Maintain exact character consistency (face, hair, clothing) for: " + matchedCharacters.map(c => c.name).join(", ") + " using the attached references.";

        for (const char of matchedCharacters) {
             const base64Data = char.avatarUrl!.split(',')[1];
             parts.push({
                inlineData: {
                    data: base64Data,
                    mimeType: "image/png"
                }
             });
        }
    }

    const finalPrompt = `Comic book panel, ${style} style. ${panelPrompt}.${referenceInstructions} High quality, vibrant colors, clear outlines, dynamic composition.`;

    parts.push({ text: finalPrompt });

    const response = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: { parts: parts },
      config: {
        aspectRatio: "1:1",
        imageSize: "1K"
      }
    }));

    let base64Image = "";
    const resParts = response.candidates?.[0]?.content?.parts;

    if (resParts) {
      for (const part of resParts) {
        if (part.inlineData && part.inlineData.data) {
          base64Image = part.inlineData.data;
          break;
        }
      }
    }

    if (!base64Image) return "";
    return `data:image/png;base64,${base64Image}`;
  } catch (error) {
    console.error("Single panel generation error:", error);
    return "";
  }
};
